/* 切换皮肤：本机立即生效；联机同步给房主（房主权威广播给其他人） */
function setSkin(id){
  if (!SKIN_IDS.includes(id)) return;
  S.skin = id;
  saveSkin(id);
  const p = S.game && S.game.player;
  if (p){ p.skin = id; p.color = skinColor(id); }
  if (S.online && S.role === 'guest') Net.sendToHost({ t: 'skin', skin: id });
  refreshSkinUI();
}
