/* ---------- 联机工具 ---------- */
const MY_COLOR = COLORS[Math.floor(Math.random() * COLORS.length)];

/* 确定性随机：同一 seed 在房主/成员端生成完全相同的食物图 */
function mulberry32(a){
  return function(){
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
/* 蛇身编解码：[{x,y}...] <-> [x,y,x,y,...]（省流量） */
function packBody(s){
  const arr = [];
  for (const p of s.snake) arr.push(p.x, p.y);
  return arr;
}
function unpackBody(arr){
  const body = [];
  for (let i = 0; i < arr.length; i += 2) body.push({ x: arr[i], y: arr[i + 1] });
  return body;
}
function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
/* 蛇的显示名：房主带「· 房主」，成员带「· 成员N」 */
function snakeLabel(s){
  let base;
  if (s.isPlayer){
    base = S.nick || '你';
    if (S.role === 'host') base += ' · 房主';
  } else if (s.isHost){
    base = (s.name || '房主') + ' · 房主';
  } else if (s.memberNo){
    base = (s.name || '成员' + s.memberNo) + ' · 成员' + s.memberNo;
  } else {
    base = s.name || '';
  }
  if (s.gifted) base += ' · 管理'; // 被房主赠送神器：身份为管理（可禁言成员）
  if (s.muted) base += ' · 禁言中';
  if (s.team && s.team === myTeamId()) base += ' · 队友'; // 同队标识（队友互撞不死）
  const sp = effectiveSpeed(s);
  if (sp !== 1) base += ' ×' + sp; // 倍速标识（全局速度不变，只是这条蛇快）
  return base;
}
function copyText(ta){
  ta.select();
  ta.setSelectionRange(0, 1e9);
  if (navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(ta.value).catch(() => document.execCommand('copy'));
  } else {
    document.execCommand('copy');
  }
  toast('已复制到剪贴板');
}

/* ---------------- 工具 ---------------- */
function clamp(v, a, b){ return v < a ? a : v > b ? b : v; }
/* 世界尺寸（格），随地图像素/加长扩界动态变化 */
function worldCols(){ return S.world.cols; }
function worldRows(){ return S.world.rows; }
function inBounds(x, y){ return x >= 0 && x < S.world.cols && y >= 0 && y < S.world.rows; }

let toastTimer = null;
/* 本地服务器模式：从成员链接打开时，进菜单后自动加入房间 */
let pendingAutoJoin = null;
function toast(msg){
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2200);
}
function showScreen(name){
  S.screen = name;
  document.querySelectorAll('.screen').forEach(el => el.classList.remove('active'));
  const el = document.getElementById('scr-' + name);
  if (el) el.classList.add('active');
  // 离开游戏画面时收起所有覆盖层（暂停/死亡/等待/胜利/黑屏/神器面板），避免"未进游戏还显示"
  if (name !== 'game'){
    ['pauseOverlay', 'respawnOverlay', 'awayOverlay', 'winOverlay', 'blackOverlay', 'compOverlay'].forEach(id => {
      const ov = document.getElementById(id);
      if (ov) ov.classList.remove('show');
    });
    const ap = document.getElementById('artifactPanel');
    if (ap) ap.classList.remove('show');
    const sp = document.getElementById('speedPanel');
    if (sp) sp.classList.remove('show');
    const si = document.getElementById('snakeInfo');
    if (si) si.classList.remove('show');
    S.mouse.over = false;
    hideRowDetail();   // 收起玩家面板 hover 详情卡
    hideManageMenu();  // 收起管理菜单
    hideIcePicker();   // 收起冰块选人弹窗
    hideItemHelp();    // 收起道具图鉴
    S.minePlacing = false;
    const ib = document.getElementById('itemBar');
    if (ib) ib.classList.remove('show');
    const cb = document.getElementById('chatBox');
    if (cb) cb.hidden = true; // 离开游戏画面：收起聊天框
  }
  if (name === 'menu') refreshRoomBar();
}

/* ---------- 主菜单：房间状态条（退出游戏后连接仍保持） ---------- */
function refreshRoomBar(){
  const bar = document.getElementById('roomBar');
  if (!S.online){ bar.hidden = true; return; }
  bar.hidden = false;

  // 房间号（仅标识展示）
  const noWrap = document.getElementById('roomBarNo');
  if (S.roomNo){
    noWrap.hidden = false;
    document.getElementById('roomBarNoText').textContent = S.roomNo;
  } else {
    noWrap.hidden = true;
  }

  // 状态感知：没进入过游戏时不显示"返回游戏"，避免误导
  const btn = document.getElementById('btnBackToGame');
  const srv = S.serverMode ? ' · 服务器模式' : '';
  let text;
  if (S.role === 'host'){
    if (S.enteredGame){
      text = `房间进行中 · 你是房主 · ${1 + S.netPeers.size} 名玩家${srv}`;
      btn.textContent = '🎮 返回游戏';
    } else {
      text = '房间已创建 · 把邀请码发给成员' + srv;
      btn.textContent = '🎮 进入游戏';
    }
  } else {
    if (S.enteredGame){
      text = '房间进行中 · 你是成员 · 已连接房主' + srv;
      btn.textContent = '🎮 返回游戏';
    } else {
      text = '已连接房主 · 等待进入游戏' + srv;
      btn.textContent = '← 回到大厅';
    }
  }
  document.getElementById('roomBarText').textContent = text;
}
function loadNick(){
  try { return localStorage.getItem(NICK_KEY) || ''; } catch(e){ return ''; }
}
function saveNick(n){
  try { localStorage.setItem(NICK_KEY, n); } catch(e){}
}

/* ---------- 食物密度设置持久化 ---------- */
function loadFoodSetting(){
  try {
    const raw = localStorage.getItem(FOOD_SETTING_KEY);
    if (raw){
      const obj = JSON.parse(raw);
      if (typeof obj.min === 'number' && typeof obj.max === 'number'){
        S.foodMin = clamp(obj.min, 1, 7);
        S.foodMax = clamp(obj.max, 1, 7);
        if (S.foodMin > S.foodMax) S.foodMin = S.foodMax;
        return;
      }
    }
  } catch(e){}
  S.foodMin = DEFAULT_FOOD_MIN;
  S.foodMax = DEFAULT_FOOD_MAX;
}
function saveFoodSetting(){
  try {
    localStorage.setItem(FOOD_SETTING_KEY, JSON.stringify({
      min: S.foodMin, max: S.foodMax,
    }));
  } catch(e){}
}

/* ---------- 胜利长度持久化 ---------- */
/* 胜利长度必须整百（向上取整），防止出现 437 这类通关长度 */
function roundWinLen(v){
  return Math.ceil(clamp(v, WIN_LEN_MIN, WIN_LEN_MAX) / 100) * 100;
}
function loadWinLen(){
  try {
    const v = parseInt(localStorage.getItem(WIN_LEN_KEY), 10);
    if (Number.isFinite(v)) S.winLen = roundWinLen(v);
  } catch(e){}
  if (!Number.isFinite(S.winLen)) S.winLen = WIN_LEN_DEFAULT;
}
function saveWinLen(){
  try { localStorage.setItem(WIN_LEN_KEY, String(S.winLen)); } catch(e){}
}

/* =========================================================
   地图尺寸选择（联机时随房主欢迎包同步）
   ========================================================= */
/* 尺寸地图无墙体：保留 isWall 供碰撞/生成逻辑统一判断，恒为 false */
function isWall(x, y){ return false; }
function isWallBlock(bx, by){ return false; }

/* 选择地图尺寸：重设世界尺寸与胜利长度 */
function setMapSize(idx, opts){
  const o = opts || {};
  const i = clamp(idx | 0, 0, MAP_SIZES.length - 1);
  const size = MAP_SIZES[i];
  S.mapSizeIdx = i;
  S.world = { cols: size.cols, rows: size.rows, artifact: !!size.artifact };
  S.winLen = roundWinLen(size.win);
  S.artifact = { immortal: false, magnet: false, speed: 1, itemImmune: false };
  if (!o.silent){
    try { localStorage.setItem(MAP_SIZE_KEY, String(i)); } catch(e){}
    refreshMapUI();
    refreshWinLenUI();
  }
}
function loadMapSize(){
  let idx = DEFAULT_MAP_IDX;
  try {
    const v = parseInt(localStorage.getItem(MAP_SIZE_KEY), 10);
    if (Number.isFinite(v)) idx = clamp(v, 0, MAP_SIZES.length - 1);
  } catch(e){}
  setMapSize(idx, { silent: true });
}


/* =========================================================
   空间哈希：食物桶
   ========================================================= */
function bucketKey(x, y){
  return Math.floor(x / BUCKET_SIZE) + ',' + Math.floor(y / BUCKET_SIZE);
}
function addFoodToBucket(f){
  const k = bucketKey(f.x, f.y);
  let set = S.game.foodBuckets.get(k);
  if (!set){ set = new Set(); S.game.foodBuckets.set(k, set); }
  set.add(f);
}
function removeFoodFromBucket(f){
  const k = bucketKey(f.x, f.y);
  const set = S.game.foodBuckets.get(k);
  if (set){
    set.delete(f);
    if (set.size === 0) S.game.foodBuckets.delete(k);
  }
}
function findNearestFood(x, y, maxRadius){
  const cx = Math.floor(x / BUCKET_SIZE);
  const cy = Math.floor(y / BUCKET_SIZE);
  for (let r = 0; r <= maxRadius; r++){
    let best = null, bestDist = Infinity;
    for (let bx = cx - r; bx <= cx + r; bx++){
      for (let by = cy - r; by <= cy + r; by++){
        if (r > 0 && Math.abs(bx - cx) !== r && Math.abs(by - cy) !== r) continue;
        const set = S.game.foodBuckets.get(bx + ',' + by);
        if (!set) continue;
        for (const f of set){
          if (f.e >= ITEM_FIRST_E) continue; // AI 寻路只找普通食物（道具当墙）
          const d = Math.abs(f.x - x) + Math.abs(f.y - y);
          if (d < bestDist){ bestDist = d; best = f; }
        }
      }
    }
    if (best) return best;
  }
  return null;
}

/* =========================================================
   游戏引擎
   ========================================================= */
function allSnakes(){
  if (!S.game) return [];
  return [S.game.player, ...S.game.ai, ...S.game.remotes];
}

function makeSnake(isPlayer, color){
  return {
    isPlayer, color,
    name: '', sid: 0, isRemote: false,
    snake: [], prevSnake: [],
    dir: { x: 1, y: 0 }, nextDir: null,
    alive: true, score: START_LEN, respawnAt: 0, // score 语义=身长（与长度恒等）
    eatenTypes: [],
    // 倍速：speed=移动格数/tick 倍率（1=标准）；speedAcc=小数倍率累积器
    speed: 1, speedAcc: 0,
    /* 道具库存：冰块/地雷手动使用；牛奶/橙子/红薯拾取后也进库存，点右侧道具栏手动使用 */
    items: { ice: 0, mine: 0, milk: 0, orange: 0, potato: 0 },
    skin: DEFAULT_SKIN,       // 皮肤 id（决定颜色与棍母蛇头像）
    muted: false,       // 被禁言（管理/房主禁言，房主可解；聊天发送被拒）
    frozenUntil: 0,   // 冰块：冻结截止时刻（performance.now）
    iceFrozen: false, // 正处于冰冻中（解冻瞬间发放无敌，用于检测状态跳转）
    iceImmuneUntil: 0,// 解冻无敌截止时刻（撞谁谁死 + 冻不住）
    slowUntil: 0,     // 地雷：0.5x 减速截止时刻
    orangeUntil: 0,   // 橙子：2x + 撞谁谁死截止时刻
    stunUntil: 0,     // 红薯：被污染烟雾熏停截止时刻（不能移动 5s）
    iceCdUntil: 0,    // 冰块：拾取冷却截止（10s 内不能二次拾取）
    team: 0,          // 所在队伍 id（0=无队；队友互穿/互救/不能互冻）
    pickEv: null,     // 房主：待通知该成员的拾取提示 {k, n}
    useEv: null,      // 房主：待通知该成员的道具使用确认 {k, n}
  };
}

/* 出生点必须与食物生成共用同一种子随机（S.rng）：
   这样"食物避开蛇身"的判定在房主/成员端看到完全相同的蛇身位置，
   消耗相同的随机序列，最终生成完全一致的食物图（联机同步的前提）。 */
function findSpawn(){
  const rng = S.rng || Math.random;
  for (let attempt = 0; attempt < 300; attempt++){
    const x = 12 + Math.floor(rng() * (S.world.cols - 24));
    const y = 12 + Math.floor(rng() * (S.world.rows - 24));
    let ok = true;
    for (const s of allSnakes()){
      if (!s.alive || !s.snake.length) continue;
      const h = s.snake[0];
      let dx = Math.abs(h.x - x); dx = Math.min(dx, S.world.cols - dx);
      let dy = Math.abs(h.y - y); dy = Math.min(dy, S.world.rows - dy);
      if (dx < 15 && dy < 15){ ok = false; break; }
    }
    if (ok) return { x, y };
  }
  // 兜底：远离所有蛇头的网格点（大地图按步长采样，开销可控）
  for (let y = 2; y < S.world.rows - 2; y += 3){
    for (let x = 2; x < S.world.cols - 2; x += 3){
      let free = true;
      for (const s of allSnakes()){
        if (!s.alive || !s.snake.length) continue;
        const h = s.snake[0];
        let dx = Math.abs(h.x - x); dx = Math.min(dx, S.world.cols - dx);
        let dy = Math.abs(h.y - y); dy = Math.min(dy, S.world.rows - dy);
        if (dx < 15 && dy < 15){ free = false; break; }
      }
      if (free) return { x, y };
    }
  }
  return { x: S.world.cols >> 1, y: S.world.rows >> 1 };
}

function respawnSnake(s){
  const pos = findSpawn();
  const body = [];
  for (let i = 0; i < START_LEN; i++){
    let x = pos.x - i;
    if (x < 0) x = 0;
    body.push({ x, y: pos.y });
  }
  s.snake = body;
  s.prevSnake = body.map(p => ({ ...p }));
  s.dir = { x: 1, y: 0 };
  s.nextDir = null;
  s.alive = true;
  s.score = START_LEN;   // score 语义=身长：与 snake.length 恒等
  s.respawnAt = 0;
  s.eatenTypes = [];
  // 重生：清除冰冻/减速/橙子/熏停 buff（库存保留，道具还没用掉）
  s.frozenUntil = 0; s.slowUntil = 0; s.orangeUntil = 0; s.stunUntil = 0;
  s.iceFrozen = false; s.iceImmuneUntil = 0;
}

/* ---------- 批量生成食物：使用当前设置的密度 ----------
   注意1：必须使用 S.rng（种子随机），这样房主与成员端
   用同一 seed 能生成完全相同的食物图（id、位置、类型一致）
   注意2：避开所有蛇身，不在蛇下面生成食物 */
function generateAllFood(){
  S.game.foods.clear();
  S.game.foodBuckets.clear();
  S.game.foodById.clear();

  // 蛇身占用表：食物不生成在蛇身上（含出生时的身体）
  const occupied = new Set();
  for (const s of allSnakes()){
    if (!s.alive) continue;
    for (const p of s.snake) occupied.add(p.x + ',' + p.y);
  }
  const rng = S.rng; // 道具与食物共用同一随机流（顺序固定→成员端生成图一致）

  /* 道具：每 4×4 格按概率刷 1 个（与食物互斥——先占位，食物生成时避开）。
     必须走 S.rng 且遍历顺序固定：成员端同种子才能生成完全一致的道具图。 */
  if (S.items.on){
    const icols = Math.ceil(S.world.cols / ITEM_GRID);
    const irows = Math.ceil(S.world.rows / ITEM_GRID);
    for (let cx = 0; cx < icols; cx++){
      for (let cy = 0; cy < irows; cy++){
        if (rng() >= ITEM_CHANCE) continue;
        const kind = Math.floor(rng() * ITEM_TYPES.length);
        for (let attempt = 0; attempt < 6; attempt++){
          const x = cx * ITEM_GRID + Math.floor(rng() * ITEM_GRID);
          const y = cy * ITEM_GRID + Math.floor(rng() * ITEM_GRID);
          if (x >= S.world.cols || y >= S.world.rows) continue;
          const key = x + ',' + y;
          if (occupied.has(key)) continue;   // 蛇身上不放道具
          if (S.game.foods.has(key)) continue;
          const f = {
            id: ++foodId, x, y,
            e: ITEM_FIRST_E + kind,          // 道具=特殊食物类型
          };
          S.game.foods.set(key, f);
          S.game.foodById.set(f.id, f);
          addFoodToBucket(f);
          occupied.add(key);                 // 占位：食物不再落到这一格
          break;
        }
      }
    }
  }

  const cols = Math.ceil(S.world.cols / FOOD_GRID);
  const rows = Math.ceil(S.world.rows / FOOD_GRID);
  const min = S.foodMin;
  const max = S.foodMax;
  const range = Math.max(1, max - min + 1);

  for (let cx = 0; cx < cols; cx++){
    for (let cy = 0; cy < rows; cy++){
      const count = min + Math.floor(rng() * range);
      for (let i = 0; i < count; i++){
        let placed = false;
        for (let attempt = 0; attempt < 8; attempt++){
          const x = cx * FOOD_GRID + Math.floor(rng() * FOOD_GRID);
          const y = cy * FOOD_GRID + Math.floor(rng() * FOOD_GRID);
          if (x >= S.world.cols || y >= S.world.rows) continue;
          if (isWall(x, y)) continue;      // 墙里不放食物
          const key = x + ',' + y;
          if (S.game.foods.has(key)) continue;
          if (occupied.has(key)) continue;   // 蛇身上不放食物
          const f = {
            id: ++foodId, x, y,
            e: Math.floor(rng() * FOOD_TYPES.length),
          };
          S.game.foods.set(key, f);
          S.game.foodById.set(f.id, f);
          addFoodToBucket(f);
          placed = true;
          break;
        }
        if (!placed) break;
      }
    }
  }
  S.game.initFoodCount = foodId;
}

function isOnSnake(x, y){
  for (const s of allSnakes()){
    if (!s.alive) continue;
    for (const p of s.snake){
      if (p.x === x && p.y === y) return true;
    }
  }
  return false;
}

function respawnFoodNear(cx, cy){
  for (let attempt = 0; attempt < 20; attempt++){
    const x = clamp(cx + Math.floor(Math.random() * 11) - 5, 0, S.world.cols - 1);
    const y = clamp(cy + Math.floor(Math.random() * 11) - 5, 0, S.world.rows - 1);
    if (isWall(x, y)) continue;         // 墙里不放食物
    const key = x + ',' + y;
    if (S.game.foods.has(key)) continue;
    if (isOnSnake(x, y)) continue;   // 不在蛇身上重生
    const f = {
      id: ++foodId, x, y,
      e: Math.floor(Math.random() * FOOD_TYPES.length),
    };
    S.game.foods.set(key, f);
    S.game.foodById.set(f.id, f);
    addFoodToBucket(f);
    // 房主记录食物增量，随快照广播给成员
    if (S.online && S.role === 'host') S.game.foodEv.add.push([f.id, f.x, f.y, f.e]);
    return;
  }
}

function createGame(seed){
  foodId = 0; // 新世界从 1 开始编号，保证成员端按种子重建后 id 一致
  S.seed = (typeof seed === 'number') ? (seed >>> 0) : (Math.random() * 0xffffffff) >>> 0;
  S.rng = mulberry32(S.seed);
  S.game = {
    player: makeSnake(true, skinColor(loadSkin())),
    ai: [],
    aiMap: new Map(),     // 成员端：sid -> 蛇（AI 与其他成员）
    remotes: [],          // 房主端：成员蛇
    foods: new Map(),
    foodById: new Map(),  // id -> 食物（用于增量同步）
    foodBuckets: new Map(),
    foodEv: { add: [], del: [] }, // 房主：待广播的食物增减
    initFoodCount: 0,
    mines: [],               // 已放置的隐形地雷 [{x, y}]（踩爆即删）
    poisons: [],             // 红薯污染区 [{x, y, t, owner, hits:[sid]}]（9×9，熏 2 人消散）
  };
  S.game.player.sid = PLAYER_SID; // 固定且唯一（面板行 key）
  S.game.player.name = S.nick || '你';
  S.skin = loadSkin();
  S.game.player.skin = S.skin;
  S.game.player.color = skinColor(S.skin);
  /* AI 蛇创建策略：
     - 房主/离线：创建真实 AI 并重生
     - 成员端：先创建等量"占位 AI"并用同一种子重生——保证随机序列消耗、
       蛇身占用位置与房主完全一致（食物图同步的前提），随后清掉；
       真正的蛇由房主快照驱动进入 g.ai */
  const guest = S.online && S.role === 'guest';
  const n = Math.max(0, Math.min(AI_COUNT, S.aiCount | 0));
  for (let i = 0; i < n; i++){
    const a = makeSnake(false, COLORS[(i + 1) % COLORS.length]);
    a.name = 'AI';
    a.sid = 1000 + i;
    S.game.ai.push(a);
  }
  respawnSnake(S.game.player);
  for (const a of S.game.ai) respawnSnake(a);
  generateAllFood();
  // 注意：占位 AI 必须在食物生成之后再清除——
  // generateAllFood 的"避让蛇身"占用表要包含它们，才能与房主完全一致
  if (guest) S.game.ai.length = 0;
  S.lastTickTime = performance.now();
  S.camInit = false;
  S.snapReceived = false;
}

function findFoodAt(x, y){
  return S.game.foods.get(x + ',' + y);
}

function dropEatenFood(s){
  const g = S.game;
  if (!g) return;
  const types = s.eatenTypes || [];
  const record = S.online && S.role === 'host';
  for (const seg of s.snake){
    const key = seg.x + ',' + seg.y;
    if (g.foods.has(key)) continue;
    const e = types.length > 0
      ? types.pop()
      : Math.floor(Math.random() * FOOD_TYPES.length);
    const f = { id: ++foodId, x: seg.x, y: seg.y, e };
    g.foods.set(key, f);
    g.foodById.set(f.id, f);
    addFoodToBucket(f);
    if (record) g.foodEv.add.push([f.id, f.x, f.y, f.e]);
  }
  s.eatenTypes = [];
}

/* =========================================================
   AI 思考
   ========================================================= */
/* AI 思考：像真人一样"尽量少转弯"——直行方向可行时大概率保持，
   只在前方受阻（撞界/撞蛇/道具格）时才转弯选路；AI 不碰道具
   （道具格当墙绕开，道具只属于玩家和联机成员）。 */
function aiChooseDir(ai){
  const head = ai.snake[0];
  const cur = ai.dir;
  const dirs = [
    { x: 1, y: 0 }, { x: -1, y: 0 },
    { x: 0, y: 1 }, { x: 0, y: -1 },
  ];
  const safe = [];
  for (const d of dirs){
    if (d.x === -cur.x && d.y === -cur.y) continue;
    const nx = head.x + d.x, ny = head.y + d.y;
    if (!inBounds(nx, ny)) continue;
    if (isWall(nx, ny)) continue;
    if (isItemAt(nx, ny)) continue;   // AI 不捡道具：当墙绕开
    let collision = false;
    for (const s of allSnakes()){
      if (!s.alive || !s.snake.length) continue;
      const start = (s === ai) ? 1 : 0;
      for (let i = start; i < s.snake.length; i++){
        if (s.snake[i].x === nx && s.snake[i].y === ny){ collision = true; break; }
      }
      if (collision) break;
    }
    if (collision) continue;
    safe.push(d);
  }
  if (!safe.length) return cur; // 无路可走：保持原方向
  /* 直行优先：当前方向安全且前方 4 格无边界 → 大概率直行 */
  const straight = safe.find(d => d.x === cur.x && d.y === cur.y);
  if (straight){
    let soon = false;
    for (let i = 1; i <= 4; i++){
      const nx = head.x + cur.x * i, ny = head.y + cur.y * i;
      if (!inBounds(nx, ny) || isWall(nx, ny) || isItemAt(nx, ny)){ soon = true; break; }
    }
    if (!soon && Math.random() < 0.9) return straight;
  }
  /* 需要转弯：朝最近食物方向选，加少量随机；轻微偏好直行方向 */
  const nearest = findNearestFood(head.x, head.y, 6);
  let best = null, bestScore = -Infinity;
  for (const d of safe){
    const nx = head.x + d.x, ny = head.y + d.y;
    let score;
    if (nearest){
      const dist = Math.abs(nearest.x - nx) + Math.abs(nearest.y - ny);
      score = -dist + Math.random() * 4;
    } else {
      score = Math.random() * 3;
    }
    if (d.x === cur.x && d.y === cur.y) score += 1.5;
    if (score > bestScore){ bestScore = score; best = d; }
  }
  return best || cur;
}

/* =========================================================
   逻辑 tick
   ========================================================= */
/* 每条蛇的有效倍速：房主本人读神器面板滑块（仅神器图生效），
   其他蛇（被赠神器的成员/AI）读自身 speed 字段。
   全局 tick 节奏（TICK_MS）不变——变的只是这条蛇自己。
   道具叠加：橙子 ×2、地雷减速 ×0.5（乘法叠加）。 */
function effectiveSpeed(s){
  if (!s) return 1;
  let v;
  if (s.isPlayer && S.role === 'host' && S.world.artifact) v = S.artifact.speed;
  else v = s.speed;
  v = Number(v);
  if (!Number.isFinite(v)) v = 1;
  if (orangeActive(s)) v *= 2;
  if (slowActive(s)) v *= 0.5;
  return clamp(v, SPEED_MIN, SPEED_MAX);
}

/* 统一死亡处理：掉食物 + 清空蛇身 + 3 秒后重生（标准流程与倍速预移动共用）
   killer=撞死它的蛇（可选）：只播报玩家之间的击杀。 */
function killSnake(s, killer){
  if (!s || !s.alive) return;
  if (killer && killer !== s && isPlayerSnake(s) && isPlayerSnake(killer)){
    feedAnnounce('kill', feedLabel(killer) + ' 击杀了 ' + feedLabel(s));
  }
  s.prevSnake = s.snake;
  dropEatenFood(s);
  s.alive = false;
  s.score = START_LEN;   // 死亡瞬间 score 归初始身长（面板/HUD 与长度一致）
  s.snake = [];
  s.respawnAt = performance.now() + RESPAWN_MS;
}

/* =========================================================
   道具系统（任何地图可开，联机房主权威）
   - 道具=特殊食物类型（e >= ITEM_FIRST_E），复用食物桶/foodEv/id
   - 四种道具均为「拾取进库存 + 右侧道具栏手动使用」：
     冰块（选人冻结 10s）/ 牛奶（+67 格）/ 橙子（1min 2x 撞谁谁死）/ 地雷（放置）
   ========================================================= */
function itemKindOf(f){ return (f && f.e >= ITEM_FIRST_E) ? ITEM_TYPES[f.e - ITEM_FIRST_E] : null; }
function isItemAt(x, y){
  const f = S.game && S.game.foods.get(x + ',' + y);
  return itemKindOf(f);
}
function frozenActive(s){ return !!(s && s.frozenUntil && s.frozenUntil > performance.now()); }
function slowActive(s){ return !!(s && s.slowUntil && s.slowUntil > performance.now()); }
function orangeActive(s){ return !!(s && s.orangeUntil && s.orangeUntil > performance.now()); }
/* 解冻无敌期：被冰冰冰冻过、解冻后 10s 内撞谁谁死，且冻不住 */
function iceImmuneActive(s){ return !!(s && s.iceImmuneUntil && s.iceImmuneUntil > performance.now()); }
/* 牛奶随机增长：67~91 格 */
function milkGrowN(){ return MILK_GROW_MIN + Math.floor(Math.random() * (MILK_GROW_MAX - MILK_GROW_MIN + 1)); }
/* 橙子豁免：有神器的人（房主不死开关 / 被赠送神器的成员）撞不死 */
function orangeImmune(o){
  if (!o) return false;
  if (o.gifted) return true;
  return o.isPlayer && S.role === 'host' && S.world.artifact && S.artifact.immortal;
}
/* 道具免疫（神器第 4 项，仅房主）：冰冰冰冻不住、地雷踩不炸 */
function itemImmuneActive(s){
  if (!s) return false;
  return !!s.isPlayer && S.role === 'host' && !!S.world.artifact && !!S.artifact.itemImmune;
}

/* ---------- 冰块：冻结目标 10s（tick 不动、渲染虚化） ----------
   道具免疫/无敌期内冻不住；已冻住的不叠加续期。返回是否冻上了。
   冻上后打 iceFrozen 标记——解冻瞬间由 iceImmuneTick 发放 10s 无敌期。 */
function freezeSnake(s){
  if (!s || !s.alive) return false;
  if (itemImmuneActive(s)) return false;
  if (iceImmuneActive(s)) return false;   // 解冻无敌期内不能再被冻
  if (frozenActive(s)) return false;      // 不能叠加：保持原到期时刻
  s.frozenUntil = performance.now() + FROZEN_MS;
  s.iceFrozen = true;
  return true;
}

/* ---------- 解冻无敌：冰冻结束的瞬间发放 10s 无敌期 ----------
   房主/单机在 tick 里调用（权威）；仅本机玩家弹提示，避免多人时刷屏。 */
function iceImmuneTick(){
  if (!S.game) return;
  const now = performance.now();
  for (const s of allSnakes()){
    if (!s.alive || !s.iceFrozen) continue;
    if (frozenActive(s)) continue;
    s.iceFrozen = false;
    s.iceImmuneUntil = now + ICE_IMMUNE_MS;
    if (s.isPlayer) toast('🛡 解冻无敌 10 秒：撞谁谁死，且冻不住了！');
  }
}

/* ---------- 解救：队友碰醒被冻住的队友 ----------
   被冻者立即解冻；救援者穿透过去，但自己被冻 1s 并自动转向空旷方向；
   四周全被蛇/墙堵死则救援者当场死亡。返回 'ok' | 'died'。 */
function rescueFrozen(r, f){
  f.frozenUntil = 0; f.iceFrozen = false; // 解除冰冻（不发无敌，那是自然解冻的待遇）
  const d = pickOpenDir(r);
  if (!d){
    toast(`💥 ${snakeLabel(r)} 碰醒队友时四面被围，当场殒命`);
    return 'died';
  }
  r.dir = d; r.nextDir = null;
  r.frozenUntil = performance.now() + RESCUE_FREEZE_MS;
  r.iceFrozen = false; r.iceImmuneUntil = 0;
  toast(`🤝 ${snakeLabel(r)} 碰醒了 ${snakeLabel(f)}，自己被冻 1 秒并转向空旷区`);
  return 'ok';
}
/* 从蛇头出发选最开阔的方向（不能掉头；按 6 格直线自由空间计分），
   四向皆堵返回 null。 */
function pickOpenDir(s){
  const h = s.snake[0];
  if (!h) return null;
  let best = null, bestScore = 0;
  for (const d of [DIRS.up, DIRS.down, DIRS.left, DIRS.right]){
    if (d.x === -s.dir.x && d.y === -s.dir.y) continue; // 不能掉头
    let score = 0;
    for (let k = 1; k <= 6; k++){
      const x = h.x + d.x * k, y = h.y + d.y * k;
      if (!inBounds(x, y) || isOnSnake(x, y)) break;
      score++;
    }
    if (score > bestScore){ bestScore = score; best = d; }
  }
  return best;
}

/* ---------- 增长 +n 格（牛奶/地雷奖励共用）----------
   每加一节按优先级找空位：① 尾巴正后方 ② 往上（y-1）
   ③ 尾巴绕圈（左右/下方，越界则沿边界转弯）；都不行则整条蛇平移让位。
   保证加满 n 格。联机时新身体随快照广播。 */
function growSnake(s, n){
  const body = s.snake;
  let added = 0;
  for (let i = 0; i < n; i++){
    if (growOneSeg(s)) added++;
    else if (!tryShiftForGrow(s)) break; // 地图实在放不下（极端满图）
  }
  s.score = body.length;
  // 长度瞬间变化：插值基线同步（drawSnake 长度不等自动 snap）
  s.prevSnake = body.map(p => ({ x: p.x, y: p.y }));
  return added;
}

function growOneSeg(s){
  const body = s.snake;
  const tail = body[body.length - 1];
  if (!tail) return false;
  const prev = body.length > 1 ? body[body.length - 2] : null;
  let dx = prev ? Math.sign(tail.x - prev.x) : -s.dir.x;
  let dy = prev ? Math.sign(tail.y - prev.y) : -s.dir.y;
  if (dx === 0 && dy === 0){ dx = -s.dir.x; dy = -s.dir.y; }
  /* 候选方向按优先级：① 尾巴正后方（延续尾部走向）
     ② 往上（y-1）——正后方被自己盘死时先往上加一格
     ③ 绕圈：左 / 右 / 下——上方也堵住就沿尾巴绕圈继续加 */
  const dirs = [{ x: dx, y: dy }, { x: 0, y: -1 }, { x: -1, y: 0 }, { x: 1, y: 0 }, { x: 0, y: 1 }];
  const seen = new Set();
  for (const d of dirs){
    const key = d.x + ',' + d.y;
    if (seen.has(key)) continue;
    seen.add(key);
    const nx = tail.x + d.x, ny = tail.y + d.y;
    if (!inBounds(nx, ny)) continue;
    // 新节不能与现有蛇身重叠（尾节自身位置除外）
    let blocked = false;
    for (let j = 0; j < body.length - 1; j++){
      if (body[j].x === nx && body[j].y === ny){ blocked = true; break; }
    }
    if (!blocked){ body.push({ x: nx, y: ny }); return true; }
  }
  return false;
}
/* 增长受阻时：尝试把整条蛇平移 1~3 格让出尾部空间（全体在界内且不撞别的蛇） */
function tryShiftForGrow(s){
  const deltas = [[1,0],[-1,0],[0,1],[0,-1],[2,0],[-2,0],[0,2],[0,-2],[3,0],[-3,0],[0,3],[0,-3]];
  for (const [dx, dy] of deltas){
    if (!canShiftSnake(s, dx, dy)) continue;
    for (const p of s.snake){ p.x += dx; p.y += dy; }
    return growOneSeg(s) ? true : (() => { for (const p of s.snake){ p.x -= dx; p.y -= dy; } return false; })();
  }
  return false;
}
function canShiftSnake(s, dx, dy){
  for (const p of s.snake){
    const x = p.x + dx, y = p.y + dy;
    if (!inBounds(x, y)) return false;
  }
  for (const o of allSnakes()){
    if (o === s || !o.alive) continue;
    for (const q of o.snake){
      for (const p of s.snake){
        if (p.x + dx === q.x && p.y + dy === q.y) return false;
      }
    }
  }
  return true;
}

/* ---------- 拾取判定：蛇头 3×3 范围内有道具即拾取（调用侧先找到道具格） ----------
   玩家与联机成员可拾取；AI 不捡（寻路已避开，此处双保险）。
   四种道具都只进库存，效果在右侧道具栏点击后手动触发。
   规则：每种库存上限 20；冰冰冰拾取后 10s 内不能再拾取（不能叠加）。 */
function pickItemAt(s, f){
  const g = S.game;
  if (!g || !f) return;
  const kind = itemKindOf(f);
  if (!kind) return;
  if (!s.isPlayer && !s.isRemote) return; // AI 不捡道具
  // 先地图上抹掉（上限满/冷却中也会消失，避免反复触发提示）
  g.foods.delete(f.x + ',' + f.y);
  removeFoodFromBucket(f);
  g.foodById.delete(f.id);
  if (S.online && S.role === 'host') g.foodEv.del.push(f.id);
  // 库存上限：每种最多 ITEM_MAX 个
  if ((s.items[kind] || 0) >= ITEM_MAX){
    if (s.isRemote) s.pickEv = { k: kind, full: true };
    else toast(`背包已满：${ITEM_NAMES[kind]}每种最多 ${ITEM_MAX} 个`);
    return;
  }
  // 冰冰冰：拾取后 10s 内不能再拾取（吃掉但不进库存）
  if (kind === 'ice' && s.iceCdUntil && performance.now() < s.iceCdUntil){
    if (s.isRemote) s.pickEv = { k: 'ice', cd: true };
    else toast('🧊 太冰了，10 秒内不能再拾取冰冰冰');
    return;
  }
  s.items[kind] = (s.items[kind] || 0) + 1;
  if (kind === 'ice') s.iceCdUntil = performance.now() + ICE_PICK_CD;
  if (s.isRemote) s.pickEv = { k: kind };
  else toast(`拾取「${ITEM_NAMES[kind]}」×1（点右侧道具栏使用）`);
}
/* 蛇头 3×3 范围内找道具（不用非得碰到；中心格优先） */
function findItemNear(x, y){
  const g = S.game;
  if (!g) return null;
  const center = findFoodAt(x, y);
  if (center && itemKindOf(center)) return center;
  for (let dy = -1; dy <= 1; dy++){
    for (let dx = -1; dx <= 1; dx++){
      if (dx === 0 && dy === 0) continue;
      const f = findFoodAt(x + dx, y + dy);
      if (f && itemKindOf(f)) return f;
    }
  }
  return null;
}

/* ---------- 红薯：污染区（房主/单机权威，tick 末尾调用） ----------
   吃下后在自己尾巴位置生成 9×9 污染区；其他蛇头路过（进入范围）即被
   熏停 5 秒（不能移动）；放置者本人与队友免疫；累计熏到 2 人后污染消散。 */
function stunnedActive(s){ return !!(s && s.stunUntil && s.stunUntil > performance.now()); }
function checkPoisons(){
  const g = S.game;
  if (!g || !g.poisons.length) return;
  const now = performance.now();
  for (let i = g.poisons.length - 1; i >= 0; i--){
    const pz = g.poisons[i];
    if (now - pz.t > POTION_MAX_MS){ g.poisons.splice(i, 1); continue; } // 5 分钟兜底消散
    for (const s of allSnakes()){
      if (!s.alive || !s.snake.length || !s.snake[0]) continue;
      if (s === pz.owner || isTeammate(s, pz.owner)) continue; // 放置者/队友免疫
      const sid = s.isPlayer ? HOST_SNAP_SID : s.sid;
      if (pz.hits.indexOf(sid) >= 0) continue; // 同一条蛇只熏一次
      const h = s.snake[0];
      if (Math.abs(h.x - pz.x) <= POTION_RADIUS && Math.abs(h.y - pz.y) <= POTION_RADIUS){
        s.stunUntil = now + POTION_STUN_MS;
        pz.hits.push(sid);
        const label = s.isPlayer ? '你' : snakeLabel(s);
        toast(`🍠 ${label} 被红薯烟雾熏停 5 秒！`);
        if (pz.hits.length >= POTION_HITS){
          g.poisons.splice(i, 1);
          toast('💨 红薯烟雾散了（已熏 2 人）');
          break;
        }
      }
    }
  }
}

/* ---------- 地雷：踩爆判定（房主/单机权威，tick 末尾调用） ----------
   放置 5 分钟后失效；爆炸范围 5×5（蛇头进入即被炸，可同时炸到多个）；
   道具免疫的房主踩不炸（雷留给你人）。 */
function checkMines(){
  const g = S.game;
  if (!g || !g.mines.length) return;
  const now = performance.now();
  for (let i = g.mines.length - 1; i >= 0; i--){
    const m = g.mines[i];
    if (now - m.t > MINE_LIFE_MS){ g.mines.splice(i, 1); continue; } // 5 分钟失效
    const victims = [];
    for (const s of allSnakes()){
      if (!s.alive || !s.snake.length) continue;
      if (itemImmuneActive(s)) continue; // 道具免疫：踩不炸
      const h = s.snake[0];
      if (Math.abs(h.x - m.x) <= MINE_RANGE && Math.abs(h.y - m.y) <= MINE_RANGE) victims.push(s);
    }
    if (!victims.length) continue;
    g.mines.splice(i, 1);
    for (const v of victims) explodeMine(v, m);
    // 放置者奖励：每炸掉一个雷 +100 格（只发一次；放置者已死/不在场则没有）
    const owner = (m.owner && m.owner.alive) ? m.owner : null;
    if (owner){
      const added = growSnake(owner, MINE_REWARD);
      toast(`💥 地雷爆炸：放置者 ${snakeLabel(owner)} 长度 +${added}`);
    }
  }
}
/* 踩爆：截掉尾部 500 格（不再散落食物，剩余 400 格直接消失），
   被炸者 10s 内 0.5x 移速。放置者奖励见 checkMines（每雷一次）。 */
function explodeMine(s, m){
  const label = s.isPlayer ? '你' : snakeLabel(s);
  if (s.snake.length <= MINE_CUT){
    killSnake(s, m.owner);
    toast(`💥 ${label} 踩到地雷，长度不足 ${MINE_CUT} 格，直接被炸死！`);
    return;
  }
  s.snake.splice(s.snake.length - MINE_CUT, MINE_CUT);
  s.score = s.snake.length;
  s.slowUntil = performance.now() + MINE_SLOW_MS;
  s.prevSnake = s.snake.map(p => ({ x: p.x, y: p.y }));
  toast(`💥 ${label} 踩到地雷：长度 -${MINE_CUT}，10 秒内移速减半`);
}

/* ---------- 玩家/成员使用冰块：弹窗选人 ---------- */
/* 道具免疫判定（冰人选人用）：房主视角看房主自己（本就在可选列表外），
   成员视角看同步来的房主免疫开关 */
function iceTargetImmune(s){
  if (S.role === 'host') return itemImmuneActive(s);
  return !!s.isHost && !!S.artifact.itemImmune;
}
/* 队友判定：同队且同队 id 非 0（AI 与无队者 team=0，永不为队友） */
function isTeammate(a, b){
  return !!(a && b && a !== b && a.team && a.team === b.team);
}
function openIcePicker(){
  const ov = document.getElementById('iceOverlay');
  const list = document.getElementById('iceTargets');
  if (!ov || !list) return;
  const p = S.game && S.game.player;
  if (!p || !p.items.ice){ toast('你还没有冰块，去地图上捡 🧊 吧'); return; }
  // 不能冰冰冰队友（联机队伍）；单机无队伍概念
  const targets = allSnakes().filter(s => s !== p && s.alive && !isTeammate(p, s));
  list.innerHTML = targets.map(s => {
    const immune = iceTargetImmune(s);
    return `
    <div class="ice-row">
      <span class="ice-dot" style="background:${s.color}"></span>
      <span class="ice-name">${escapeHtml(snakeLabel(s))}${immune ? ' 🛡' : ''}</span>
      <button class="btn small ice-btn" data-sid="${s.sid}"${immune ? ' disabled title="不受道具影响，冻不住"' : ''}>🧊 冻住</button>
    </div>`;
  }).join('') || '<div class="ice-empty">场上没有可选目标</div>';
  ov.classList.add('show');
}
function hideIcePicker(){
  const ov = document.getElementById('iceOverlay');
  if (ov) ov.classList.remove('show');
}
function useIce(sid){
  const p = S.game && S.game.player;
  if (!p || !p.items.ice) return;
  const target = allSnakes().find(s => s.sid === sid);
  if (!target || target === p){ return; }
  if (isTeammate(p, target)){ toast('🤝 不能冰冰冰队友'); return; }
  if (S.online && S.role === 'guest'){
    // 成员：请求房主权威执行（本地先扣，失败时快照会恢复）
    Net.sendToHost({ t: 'item', k: 'ice', target: sid });
    p.items.ice--;
    toast(`🧊 已请求冻住 ${snakeLabel(target)}`);
  } else {
    const ok = freezeSnake(target);
    if (ok){
      p.items.ice--;
      toast(`🧊 ${snakeLabel(target)} 被冻住 10 秒`);
      feedAnnounce('skill', feedLabel(p) + ' 使用 🧊冰冰冰 冻住了 ' + feedLabel(target));
    } else {
      toast(itemImmuneActive(target) ? `🛡 ${snakeLabel(target)} 不受道具影响，冻不住`
        : iceImmuneActive(target) ? `🛡 ${snakeLabel(target)} 解冻无敌中，冻不住`
        : `🧊 ${snakeLabel(target)} 已经被冻住了（不能叠加）`);
    }
  }
  hideIcePicker();
  refreshItemBar();
}

/* ---------- 玩家/成员使用牛奶：喝下，身长随机 +67~91 格 ---------- */
function useMilk(){
  const p = S.game && S.game.player;
  if (!p || !p.items.milk) return;
  if (S.online && S.role === 'guest'){
    // 成员：请求房主权威执行（本地先扣，失败时快照会恢复）
    Net.sendToHost({ t: 'item', k: 'milk' });
    p.items.milk--;
    toast('🥛 已请求喝下牛奶');
  } else {
    p.items.milk--;
    const n = milkGrowN();
    const added = growSnake(p, n);
    toast(`🥛 喝下牛奶，增长 ${added} 格`);
    feedAnnounce('skill', feedLabel(p) + ' 使用 🥛牛奶 增长 ' + added + ' 格');
  }
  refreshItemBar();
}

/* ---------- 玩家/成员使用红薯：在尾巴处生成 9×9 污染区 ----------
   放置后立即生效（含放置者自己周围的蛇）；房主权威，成员请求后由房主创建。 */
function spawnPoison(s){
  if (!S.game || !s || !s.snake.length) return;
  const tail = s.snake[s.snake.length - 1];
  S.game.poisons.push({ x: tail.x, y: tail.y, t: performance.now(), owner: s, hits: [] });
  toast(`🍠 ${s.isPlayer ? '你' : snakeLabel(s)} 的尾巴污染了一片区域（9×9，熏 2 人消散）`);
}
function usePotato(){
  const p = S.game && S.game.player;
  if (!p || !p.items.potato) return;
  if (S.online && S.role === 'guest'){
    Net.sendToHost({ t: 'item', k: 'potato' });
    p.items.potato--; // 本地先扣，房主权威为准（快照恢复）
    toast('🍠 已请求放置红薯烟雾');
  } else {
    p.items.potato--;
    spawnPoison(p);
    feedAnnounce('skill', feedLabel(p) + ' 使用 🍠红薯 布置了污染区');
  }
  refreshItemBar();
}

/* ---------- 玩家/成员使用橙子：吃下，10 秒 2x + 撞谁谁死（不能叠加） ---------- */
function useOrange(){
  const p = S.game && S.game.player;
  if (!p || !p.items.orange) return;
  if (orangeActive(p)){ toast('🍊 橙子效果仍在，不能叠加（未消耗）'); return; }
  if (S.online && S.role === 'guest'){
    Net.sendToHost({ t: 'item', k: 'orange' });
    p.items.orange--;
    toast('🍊 已请求吃下橙子');
  } else {
    p.items.orange--;
    p.orangeUntil = performance.now() + ORANGE_MS;
    toast('🍊 吃下橙子：10 秒内 2x 移速，撞谁谁死！');
    feedAnnounce('skill', feedLabel(p) + ' 使用 🍊橙子 进入狂暴');
  }
  refreshItemBar();
}

/* ---------- 玩家/成员使用地雷：进入放置模式，点击地图安放 ---------- */
function enterMinePlace(){
  const p = S.game && S.game.player;
  if (!p || !p.items.mine){ toast('你还没有地雷，去地图上捡 💣 吧'); return; }
  S.minePlacing = true;
  hideItemHelp();
  toast('💣 点击地图任意位置放置隐形地雷（Esc / 右键取消）');
}
function cancelMinePlace(){
  if (S.minePlacing){ S.minePlacing = false; toast('已取消放置地雷'); }
}
function placeMineAt(wx, wy){
  const p = S.game && S.game.player;
  if (!p || !p.items.mine){ S.minePlacing = false; return; }
  if (!inBounds(wx, wy)){ toast('超出地图范围'); return; }
  if (isOnSnake(wx, wy)){ toast('不能放在蛇身上'); return; }
  if (S.online && S.role === 'guest'){
    Net.sendToHost({ t: 'item', k: 'mine', x: wx, y: wy });
    p.items.mine--; // 本地先扣，房主校验失败时快照恢复
  } else {
    p.items.mine--;
    S.game.mines.push({ x: wx, y: wy, t: performance.now(), owner: p });
    feedAnnounce('skill', feedLabel(p) + ' 使用 💣地雷 布置在地图上');
  }
  S.minePlacing = false;
  toast('💣 地雷已放置（隐形，谁踩谁炸；5 分钟后失效）');
  refreshItemBar();
}

/* ---------- 道具图鉴 ---------- */
function showItemHelp(){
  const ov = document.getElementById('itemHelpOverlay');
  if (ov) ov.classList.add('show');
}
function hideItemHelp(){
  const ov = document.getElementById('itemHelpOverlay');
  if (ov) ov.classList.remove('show');
}

/* ---------- 侧边道具栏 ---------- */
function refreshItemBar(){
  const bar = document.getElementById('itemBar');
  if (!bar) return;
  const p = S.game && S.game.player;
  const show = !!(S.items.on && p && ((p.items.ice || 0) > 0 || (p.items.mine || 0) > 0
    || (p.items.milk || 0) > 0 || (p.items.orange || 0) > 0 || (p.items.potato || 0) > 0));
  bar.classList.toggle('show', show);
  if (!show) return;
  for (const kind of ['ice', 'milk', 'orange', 'mine', 'potato']){
    const cell = bar.querySelector('#item' + kind[0].toUpperCase() + kind.slice(1));
    if (!cell) continue;
    const n = p.items[kind] || 0;
    cell.classList.toggle('has', n > 0);
    const c = cell.querySelector('.it-count');
    if (c) c.textContent = '×' + n;
  }
}

/* 成员端：房主通知的拾取提示（一次性） */
function showPickToast(pick){
  if (!pick) return;
  if (pick.full){ toast(`背包已满：${ITEM_NAMES[pick.k] || '道具'}每种最多 ${ITEM_MAX} 个`); return; }
  if (pick.cd){ toast('🧊 太冰了，10 秒内不能再拾取冰冰冰'); return; }
  if (pick.k === 'milk') toast('🥛 拾取「牛奶」×1（点右侧道具栏使用）');
  else if (pick.k === 'orange') toast('🍊 拾取「橙子」×1（点右侧道具栏使用）');
  else if (pick.k === 'ice') toast('🧊 拾取「冰冰冰」×1（点右侧道具栏使用）');
  else if (pick.k === 'mine') toast('💣 拾取「地雷」×1（点右侧道具栏放置）');
}

/* 成员端：房主确认的道具使用结果（一次性） */
function showUseToast(use){
  if (!use) return;
  if (use.ok === false){
    if (use.k === 'orange') toast('🍊 橙子效果仍在，不能叠加（未消耗）');
    else if (use.k === 'ice') toast('🧊 不能冰冰冰队友（未消耗）');
    else toast('道具使用失败（未消耗）');
    return;
  }
  if (use.k === 'milk') toast('🥛 喝下牛奶，增长 ' + (use.n || MILK_GROW_MIN) + ' 格');
  else if (use.k === 'orange') toast('🍊 吃下橙子：10 秒内 2x 移速，撞谁谁死！');
  else if (use.k === 'ice') toast('🧊 冻住成功（10 秒）');
  else if (use.k === 'mine') toast('💣 地雷放置成功');
  else if (use.k === 'potato') toast('🍠 红薯烟雾已布置（9×9，熏 2 人消散）');
}

/* 倍速预移动：本 tick 需要移动 steps(>=2) 格的蛇逐格前移，
   每格都做完整的碰撞/吃食物判定。其他蛇本 tick 尚未移动
   （标准流程在后面），故用它们当前的身体判定——与标准流程
   「以旧身体判定」的语义一致（如头尾交换位照样死）。 */
function preMoveSnake(s, steps){
  const g = S.game;
  s.prevSnake = s.snake;
  const im = !!S.world.artifact && S.role === 'host' &&
    ((s.isPlayer && S.artifact.immortal) || !!s.gifted);
  for (let i = 0; i < steps; i++){
    if (!s.alive) break;
    let nh = { x: s.snake[0].x + s.dir.x, y: s.snake[0].y + s.dir.y };
    /* 房主不死：撞墙自动向两边转向（沿边界滑行，不死） */
    if (im && !inBounds(nh.x, nh.y)){
      const turns = s.dir.x !== 0 ? [{ x: 0, y: 1 }, { x: 0, y: -1 }] : [{ x: 1, y: 0 }, { x: -1, y: 0 }];
      let turned = false;
      for (const d of turns){
        const tx = s.snake[0].x + d.x, ty = s.snake[0].y + d.y;
        if (inBounds(tx, ty)){ s.dir = d; nh = { x: tx, y: ty }; turned = true; break; }
      }
      if (!turned) nh = { x: s.snake[0].x, y: s.snake[0].y }; // 极端角落：原地踏步
    }
    if (!im){
      if (!inBounds(nh.x, nh.y) || isWall(nh.x, nh.y)){ killSnake(s); return; }
      if (s.snake.length < SELF_IMMUNE_LEN){
        for (let j = 1; j < s.snake.length; j++){
          if (s.snake[j].x === nh.x && s.snake[j].y === nh.y){ killSnake(s); return; }
        }
      }
    }
    for (const o of allSnakes()){
      if (o === s || !o.alive) continue;
      let hitIdx = -1;
      for (let j = 0; j < o.snake.length; j++){
        if (o.snake[j].x === nh.x && o.snake[j].y === nh.y){ hitIdx = j; break; }
      }
      if (hitIdx < 0) continue;
      /* 队友：互穿不死；碰醒被冻的队友（救援者冻 1s + 自动转向，四面皆蛇则死） */
      if (isTeammate(s, o)){
        if (frozenActive(o) && rescueFrozen(s, o) === 'died'){ killSnake(s); return; }
        continue;
      }
      /* 解冻无敌：撞谁谁死（神器豁免除外），自己不死 */
      if (iceImmuneActive(s)){
        if (!orangeImmune(o)) killSnake(o, s);
        continue;
      }
      /* 橙子：撞谁谁死（神器豁免：对方不死，自己照常判定） */
      if (orangeActive(s) && !orangeImmune(o)){ killSnake(o, s); continue; }
      if (!im){ killSnake(s, o); if (hitIdx === 0 && !(orangeActive(s) && orangeImmune(o))) killSnake(o, s); return; }
      killSnake(o, s); // 不死之身：撞谁谁死（含头对头同归），自己继续
    }
    // 移动一格：吃到食物则生长（score/长度同步 +1），否则缩尾
    // 道具先触发效果（牛奶在旧身尾部增长，随后构造的新身体会包含新节）
    const f = findFoodAt(nh.x, nh.y);
    const isItem = !!(f && itemKindOf(f));
    const nearItem = isItem ? f : findItemNear(nh.x, nh.y); // 3×3 范围内即可拾取道具
    if (nearItem) pickItemAt(s, nearItem);
    const newSnake = [nh, ...s.snake];
    if (f && !isItem){
      g.foods.delete(nh.x + ',' + nh.y);
      removeFoodFromBucket(f);
      g.foodById.delete(f.id);
      if (S.online && S.role === 'host') g.foodEv.del.push(f.id);
      s.score++; // 吃一个普通食物长一格
      s.eatenTypes.push(f.e);
      respawnFoodNear(nh.x, nh.y);
    } else {
      newSnake.pop();
    }
    s.snake = newSnake;
  }
}

function tick(){
  if (!S.game || S.paused) return;
  const g = S.game;
  iceImmuneTick(); // 冰冻结束的瞬间发放 10s 解冻无敌期

  for (const s of allSnakes()){
    if (!s.alive) continue;
    if (s.nextDir){
      if (!(s.nextDir.x === -s.dir.x && s.nextDir.y === -s.dir.y)){
        s.dir = s.nextDir;
      }
      s.nextDir = null;
    }
  }

  for (const ai of g.ai){
    if (!ai.alive) continue;
    ai.dir = aiChooseDir(ai);
  }

  /* 倍速：累积本 tick 移动格数（0.5x~10x，长期平均 = 倍速）。
     >=2 格 → 预移动逐格前移；=1 格 → 下方标准流程；
     =0 格 → 本 tick 不动（仍占位，别人撞它照样死）。
     被冰块冻住的蛇：本 tick 不动（10s 内不能移动）。 */
  for (const s of allSnakes()){
    if (!s.alive) continue;
    if (frozenActive(s) || stunnedActive(s)){ s.tickSteps = 0; s.speedAcc = 0; continue; }
    s.speedAcc = (s.speedAcc || 0) + effectiveSpeed(s);
    s.tickSteps = Math.floor(s.speedAcc);
    s.speedAcc -= s.tickSteps;
  }
  for (const s of allSnakes()){
    if (!s.alive || !s.tickSteps || s.tickSteps < 2) continue;
    preMoveSnake(s, s.tickSteps);
  }

  const newHeads = new Map();
  for (const s of allSnakes()){
    if (!s.alive || s.tickSteps !== 1) continue; // 仅标准 1 格移动的蛇走本流程（倍速蛇已预移动/不动）
    const h = s.snake[0];
    newHeads.set(s, { x: h.x + s.dir.x, y: h.y + s.dir.y });
  }

  const dead = new Map(); // 受害者 → 凶手（用于击杀播报）
  for (const s of allSnakes()){
    if (!s.alive || !newHeads.has(s)) continue;
    let nh = newHeads.get(s);
    /* 神器·不死：仅房主端权威生效（成员端跟随快照）。
       房主本人的不死由神器面板开关控制；成员被房主「赠送神器」后
       （rs.gifted）同样获得不死之身，不受房主开关影响。 */
    const im = !!S.world.artifact && S.role === 'host' &&
      ((s.isPlayer && S.artifact.immortal) || !!s.gifted);

    /* 房主不死：撞墙自动向两边转向（沿边界滑行，不死） */
    if (im && !inBounds(nh.x, nh.y)){
      const turns = s.dir.x !== 0 ? [{ x: 0, y: 1 }, { x: 0, y: -1 }] : [{ x: 1, y: 0 }, { x: -1, y: 0 }];
      let turned = false;
      for (const d of turns){
        const tx = s.snake[0].x + d.x, ty = s.snake[0].y + d.y;
        if (inBounds(tx, ty)){ s.dir = d; nh = { x: tx, y: ty }; newHeads.set(s, nh); turned = true; break; }
      }
      if (!turned) nh = { x: s.snake[0].x, y: s.snake[0].y }; // 极端角落：原地踏步
    }

    if (!im){
      if (!inBounds(nh.x, nh.y)){ dead.set(s, null); continue; }
      if (isWall(nh.x, nh.y)){ dead.set(s, null); continue; }   // 撞墙即死

      /* 长度达到 SELF_IMMUNE_LEN 后获得"钢筋蛇身"：撞到自己不会死。
         判定在房主端权威执行，成员端通过快照自动一致。 */
      if (s.snake.length < SELF_IMMUNE_LEN){
        for (let i = 1; i < s.snake.length; i++){
          if (s.snake[i].x === nh.x && s.snake[i].y === nh.y){ dead.set(s, null); break; }
        }
      }
    }

    for (const o of allSnakes()){
      if (o === s || !o.alive) continue;
      for (let i = 0; i < o.snake.length; i++){
        if (o.snake[i].x === nh.x && o.snake[i].y === nh.y){
          /* 队友：互穿不死；碰醒被冻的队友（救援者冻 1s + 自动转向，四面皆蛇则死） */
          if (isTeammate(s, o)){
            if (frozenActive(o) && rescueFrozen(s, o) === 'died') dead.set(s, null);
            break;
          }
          /* 解冻无敌：撞谁谁死（神器豁免除外），自己不死 */
          if (iceImmuneActive(s)){
            if (!orangeImmune(o)) dead.set(o, s);
            break;
          }
          /* 橙子：撞谁谁死（神器豁免：对方不死，s 照常判定） */
          const oKill = orangeActive(s) && !orangeImmune(o);
          if (oKill){ dead.set(o, s); break; }
          if (!im) dead.set(s, o);           // 房主不死：只死对方
          // 神器豁免：连"头对头同归"都不牵连对方（橙子撞神器=完全无伤）
          if ((im || i === 0) && !(orangeActive(s) && orangeImmune(o))) dead.set(o, s);
          break;
        }
      }
    }
  }

  for (const s of allSnakes()){
    if (!s.alive) continue;
    const nh = newHeads.get(s);
    if (!nh) continue;   // 倍速预移动/本 tick 不动的蛇不走标准流程
    s.prevSnake = s.snake;

    if (dead.has(s)){
      killSnake(s, dead.get(s));
      continue;
    }
    // 道具先触发效果（牛奶在旧身尾部增长，随后构造的新身体包含新节）
    const f = findFoodAt(nh.x, nh.y);
    const isItem = !!(f && itemKindOf(f));
    const nearItem = isItem ? f : findItemNear(nh.x, nh.y); // 3×3 范围内即可拾取道具
    if (nearItem) pickItemAt(s, nearItem);
    const newSnake = [nh, ...s.snake];
    if (f && !isItem){
      g.foods.delete(nh.x + ',' + nh.y);
      removeFoodFromBucket(f);
      g.foodById.delete(f.id);
      if (S.online && S.role === 'host') g.foodEv.del.push(f.id);
      s.score++; // 吃一个普通食物长一格
      s.eatenTypes.push(f.e);
      respawnFoodNear(nh.x, nh.y);
    } else {
      newSnake.pop();
    }
    s.snake = newSnake;
  }

  /* 地雷：踩爆判定（隐形，谁的头踩到谁炸） */
  checkMines();
  /* 红薯：污染区熏停判定（路过 9×9 区域停 5s） */
  checkPoisons();

  const now2 = performance.now();
  for (const s of allSnakes()){
    if (!s.alive && s.respawnAt && now2 >= s.respawnAt) respawnSnake(s);
  }

  S.lastTickTime = now2;

  /* 神器·吸附食物：房主蛇头 5×5 范围内的食物每 tick 飞向蛇头一步 */
  artifactMagnet();

  /* 胜利判定：身长达到设定值且正好为整百即获胜（房主/单机权威判定，成员端由房主广播）。
     防止蛇无限增长占满地图。 */
  if (!S.winner && !(S.online && S.role === 'guest')){
    let best = null;
    for (const s of allSnakes()){
      if (s.alive && s.snake.length >= S.winLen && s.snake.length % 100 === 0){
        if (!best || s.snake.length > best.snake.length) best = s;
      }
    }
    if (best){ triggerWin(best); return; } // 本 tick 已触发胜利，不再广播快照
    // 已超过胜利长度但不是整百（牛奶/地雷跳格）：提示还需冲到下一个整百
    const p = g.player;
    if (p && p.alive && p.snake.length >= S.winLen){
      const next = (Math.floor(p.snake.length / 100) + 1) * 100;
      if (S.winHint !== next){
        S.winHint = next;
        toast(`身长已超过 ${S.winLen}，但通关必须整百：冲到 ${next}！`);
      }
    }
  }

  /* 竞赛模式：时间到 → 房主权威结算（本 tick 不再广播） */
  if (S.comp.on && !S.comp.over && !S.winner && S.online && S.role === 'host'){
    if (performance.now() >= S.comp.endAt){ endCompetition(); return; }
  }

  // 房主：每 tick 向所有成员广播快照
  if (S.online && S.role === 'host') hostBroadcast();
}

/* =========================================================
   神器（仅 1600×1600 房主有神器版地图，房主端权威）
   ========================================================= */
function hostImmortal(){
  return !!S.world.artifact && S.role === 'host' && !!(S.game && S.game.player.alive) && S.artifact.immortal;
}

/* 吸附食物：范围 5×5，食物逐格飞向蛇头，飞到蛇头格即吃掉 */
/* 神器·磁吸：蛇头 5×5 范围内的食物每 tick 飞向蛇头一步，碰到即吃掉。
   目标 = 房主本人（神器面板开关控制）+ 被赠送神器的成员（常驻）。 */
function artifactMagnet(){
  if (!S.world.artifact || S.role !== 'host') return;
  const g = S.game;
  if (!g) return;
  const targets = [];
  const p = g.player;
  if (p && p.alive && p.snake.length && S.artifact.magnet) targets.push(p);
  for (const s of allSnakes()){
    if (s === p) continue;
    if (s.gifted && s.alive && s.snake.length) targets.push(s);
  }
  for (const t of targets) magnetFor(t);
}

function magnetFor(p){
  const g = S.game;
  const h = p.snake[0];
  const movers = [];
  for (let dy = -2; dy <= 2; dy++){
    for (let dx = -2; dx <= 2; dx++){
      if (dx === 0 && dy === 0) continue;
      const f = g.foods.get((h.x + dx) + ',' + (h.y + dy));
      if (f) movers.push(f);
    }
  }
  for (const f of movers){
    const nx = f.x + Math.sign(h.x - f.x);
    const ny = f.y + Math.sign(h.y - f.y);
    const fx = f.x + ',' + f.y;
    if (nx === h.x && ny === h.y){
      // 飞到蛇头格：直接吃掉（score 与长度必须同步 +1，否则「积分和长度不一样」）
      g.foods.delete(fx); removeFoodFromBucket(f); g.foodById.delete(f.id);
      g.foodEv.del.push(f.id);
      p.score++; p.eatenTypes.push(f.e);
      // 本 tick 身体已更新完，直接在尾部补一节（等效于吃到食物不缩尾）
      const tail = p.snake[p.snake.length - 1];
      if (tail) p.snake.push({ x: tail.x, y: tail.y });
      continue;
    }
    const nk = nx + ',' + ny;
    if (g.foods.has(nk)) continue; // 目标被占用则原地不动
    g.foods.delete(fx); removeFoodFromBucket(f);
    f.x = nx; f.y = ny;
    g.foods.set(nk, f); addFoodToBucket(f);
    g.foodEv.del.push(f.id);
    g.foodEv.add.push([f.id, f.x, f.y, f.e]);
  }
}

/* ---------- 胜利 ---------- */
function triggerWin(s){
  S.winner = {
    name: s.isPlayer ? (S.nick || '你') : (s.name || 'AI'),
    color: s.color,
    len: s.snake.length,
    isPlayer: !!s.isPlayer,
    sid: s.isPlayer ? HOST_SNAP_SID : s.sid,
  };
  // 皇冠累计：该蛇本局夺冠次数 +1（继续模式下不清零，重开新局才清零）
  s.crowns = (s.crowns || 0) + 1;
  if (S.tickTimer){ clearInterval(S.tickTimer); S.tickTimer = null; }
  if (S.online && S.role === 'host'){
    // 逐人发送：mine=true 只有夺冠者本人（其他人只弹小提示，不抢画面）
    const base = { t: 'win', name: S.winner.name, len: S.winner.len, color: S.winner.color, crowns: s.crowns, sid: S.winner.sid };
    S.netPeers.forEach((rs, id) => Net.sendToPeer(id, Object.assign({}, base, { mine: rs === s })));
  }
  /* 通关只给获胜者本人弹结算窗；其他人只有拾取式小弹窗。
     房主视角：自己夺冠 → 弹窗；AI 夺冠 → 房主兜底弹窗（否则没人能点继续）；
     成员夺冠 → 房主仅小提示（弹窗由夺冠成员自己显示）。 */
  const iWin = !!s.isPlayer;
  if (iWin || !s.isRemote || !S.online) showWinOverlay();
  toast('🏆 ' + S.winner.name + ' 身长达到 ' + S.winner.len + '，获得胜利！');
}

/* ---------- 胜利后「继续」：不清场，夺冠蛇重置长度，累计皇冠 ---------- */
function continueGame(){
  if (!S.winner) return;
  S.winner = null;
  S.winHint = 0;
  S.continued = true;
  document.getElementById('winOverlay').classList.remove('show');
  // 已达胜利长度的蛇重置为初始长度（分数清零，皇冠保留）
  for (const s of allSnakes()){
    if (s.alive && s.snake.length >= S.winLen) respawnSnake(s);
  }
  if (!(S.online && S.role === 'guest')){
    if (S.tickTimer) clearInterval(S.tickTimer);
    S.tickTimer = setInterval(tick, TICK_MS);
  }
  if (S.online && S.role === 'host') Net.broadcast({ t: 'continue' });
  toast('👑 继续！已夺冠的蛇已重置长度，冲向下一顶皇冠');
}

/* =========================================================
   竞赛模式（仅房主在联机大厅配置）：
   - 房主进游戏时开始倒计时，并向全员广播剩余秒数（不做时钟同步，
     成员以收到时刻为基准本地倒计时，局域网误差可忽略）
   - 时间到：房主权威结算，按身长排名，全员显示排名界面
   ========================================================= */
const COMP_MINUTES = [5, 10, 15, 20, 30, 60];

/* 从联机大厅读取竞赛配置（建房入口调用） */
function readCompSetting(){
  const onEl = document.getElementById('compOn');
  const minEl = document.getElementById('compMinutes');
  S.comp.on = !!(onEl && onEl.checked);
  S.comp.minutes = clamp(parseInt(minEl && minEl.value, 10) || 10, 1, 180);
  S.comp.endAt = 0;
  S.comp.over = false;
}

/* 房主：进入游戏时启动竞赛计时并广播 */
function startCompetition(){
  if (!S.comp.on) return;
  S.comp.over = false;
  S.comp.endAt = performance.now() + S.comp.minutes * 60000;
  document.getElementById('compOverlay').classList.remove('show');
  if (S.online && S.role === 'host'){
    Net.broadcast({ t: 'comp', on: true, secs: Math.round(S.comp.minutes * 60) });
  }
  toast(`🏁 竞赛模式开始：${S.comp.minutes} 分钟，时间到按身长排名`);
}

/* 房主：时间到，权威结算并广播排名 */
function endCompetition(){
  if (!S.comp.on || S.comp.over) return;
  S.comp.over = true;
  if (S.tickTimer){ clearInterval(S.tickTimer); S.tickTimer = null; }
  const ranks = allSnakes()
    .filter(s => s.alive)
    .sort((a, b) => b.score - a.score || b.snake.length - a.snake.length)
    .map(s => ({
      name: s.isPlayer ? (S.nick || '你') : (s.name || 'AI'),
      color: s.color,
      score: s.score,
      isPlayer: !!s.isPlayer,
      isHost: !!s.isHost,
      memberNo: (typeof s.memberNo === 'number') ? s.memberNo : null,
    }));
  if (S.online && S.role === 'host') Net.broadcast({ t: 'compEnd', ranks });
  showCompOverlay(ranks);
  toast('🏁 竞赛结束！');
}

function showCompOverlay(ranks){
  const ov = document.getElementById('compOverlay');
  const box = document.getElementById('compRanks');
  if (!ov || !box) return;
  const rows = (ranks || []).map((r, i) => {
    const tag = r.isPlayer ? '（你）' : (r.isHost ? ' · 房主' : (r.memberNo ? ' · 成员' + r.memberNo : ''));
    const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : (i + 1) + '.';
    return `<div class="comp-rank-row">
      <span class="cr-medal">${medal}</span>
      <span class="cr-dot" style="background:${r.color}"></span>
      <span class="cr-name">${escapeHtml(r.name)}${tag}</span>
      <span class="cr-score">${r.score}</span>
    </div>`;
  }).join('');
  box.innerHTML = rows || '<div class="comp-empty">没有存活玩家</div>';
  ov.classList.add('show');
}

function hideCompOverlay(){
  const ov = document.getElementById('compOverlay');
  if (ov) ov.classList.remove('show');
}

/* 成员：房主开/关竞赛（含重新开始时的重播） */
function applyComp(msg){
  if (msg && msg.on && typeof msg.secs === 'number' && msg.secs > 0){
    S.comp.on = true;
    S.comp.over = false;
    S.comp.endAt = performance.now() + msg.secs * 1000;
    S.comp.minutes = Math.max(1, Math.round(msg.secs / 60));
    hideCompOverlay();
    toast(`🏁 竞赛模式开始：${S.comp.minutes} 分钟`);
  } else {
    S.comp.on = false;
  }
}

/* 成员：房主广播的最终排名 */
function applyCompEnd(msg){
  S.comp.over = true;
  showCompOverlay((msg && msg.ranks) || []);
}

/* HUD 倒计时（updateUI 每帧调用） */
function refreshCompTimer(){
  const el = document.getElementById('hudCompTimer');
  if (!el) return;
  if (S.comp.on && !S.comp.over){
    const remain = Math.max(0, (S.comp.endAt - performance.now()) / 1000);
    const mm = Math.floor(remain / 60), ss = Math.floor(remain % 60);
    el.textContent = '⏱ ' + mm + ':' + String(ss).padStart(2, '0');
    el.hidden = false;
  } else {
    el.hidden = true;
  }
}

function showWinOverlay(){
  const ov = document.getElementById('winOverlay');
  if (!S.winner){ ov.classList.remove('show'); return; }
  document.getElementById('winMsg').textContent = S.winner.name + ' 获得胜利！';
  document.getElementById('winMsg').style.color = S.winner.color || '#ffd93d';
  document.getElementById('winLen').textContent = '身长 ' + S.winner.len + ' / ' + S.winLen;
  ov.classList.add('show');
}

function applyWin(msg){
  /* 只有夺冠者本人显示结算弹窗；其他人只弹拾取式小提示（跟拾取道具一样） */
  if (!msg.mine){
    toast('🏆 ' + (msg.name || '房主') + ' 身长达到 ' + (msg.len || 0) + '，获得胜利！');
    return;
  }
  S.winner = {
    name: msg.name || '房主',
    color: msg.color || '#ffd93d',
    len: msg.len || 0,
    isPlayer: true,
    crowns: msg.crowns || 0,
    sid: msg.sid || 0,
  };
  showWinOverlay();
  toast('🏆 ' + S.winner.name + ' 获得胜利！');
}

/* 成员：房主点了「继续」——本地同步（房主权威模拟，快照会重置夺冠蛇长度） */
function applyContinue(){
  S.winner = null;
  S.continued = true;
  document.getElementById('winOverlay').classList.remove('show');
  toast('👑 房主选择了继续，冲下一顶皇冠！');
}

/* =========================================================
   渲染
   ========================================================= */
function resizeCanvas(){
  // 手机端留更小边距，尽量撑满屏幕
  const narrow = window.innerWidth < 640;
  const margin = narrow ? 10 : 20;
  const maxW = Math.min(1280, window.innerWidth - margin);
  const maxH = Math.min(820, window.innerHeight - margin);
  canvas.width = Math.max(320, Math.floor(maxW));
  canvas.height = Math.max(240, Math.floor(maxH));
  canvas.style.width = canvas.width + 'px';
  canvas.style.height = canvas.height + 'px';
  S.camInit = false;
}
window.addEventListener('resize', () => {
  if (S.screen === 'game') resizeCanvas();
});

function updateCamera(){
  if (!S.game) return;
  const p = S.game.player;
  if (!p.snake.length) return;
  const h = p.snake[0];
  const worldWpx = S.world.cols * CELL, worldHpx = S.world.rows * CELL;
  const tx = clamp(h.x * CELL + CELL / 2 - canvas.width / 2, 0, Math.max(0, worldWpx - canvas.width));
  const ty = clamp(h.y * CELL + CELL / 2 - canvas.height / 2, 0, Math.max(0, worldHpx - canvas.height));
  if (!S.camInit){ S.camX = tx; S.camY = ty; S.camInit = true; }
  else {
    S.camX += (tx - S.camX) * 0.22;
    S.camY += (ty - S.camY) * 0.22;
  }
}

function shade(hex, amt){
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  r = clamp(Math.round(r + r * amt), 0, 255);
  g = clamp(Math.round(g + g * amt), 0, 255);
  b = clamp(Math.round(b + b * amt), 0, 255);
  return `rgb(${r},${g},${b})`;
}

function roundRect(x, y, w, h, r){
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawSnake(s, t){
  const cur = s.snake;
  const prev = s.prevSnake;
  const n = cur.length;
  if (!n) return;
  const canLerp = prev && prev.length === n;
  /* 被冰块冻住 / 红薯烟雾熏停：半透明虚化 */
  const frozen = frozenActive(s);
  const stunned = stunnedActive(s);
  if (frozen || stunned) ctx.globalAlpha = 0.45;

  for (let i = n - 1; i >= 0; i--){
    const c = cur[i];
    let px = c.x, py = c.y;
    if (canLerp){
      const p = prev[i];
      const dx = c.x - p.x, dy = c.y - p.y;
      if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1){
        px = p.x + dx * t;
        py = p.y + dy * t;
      }
    }
    const x = px * CELL;
    const y = py * CELL;
    const pad = 1.5;

    if (i === 0 && s.isPlayer){
      ctx.shadowColor = n >= SELF_IMMUNE_LEN ? '#ffd93d' : s.color;
      ctx.shadowBlur = 18;
    } else if (i === 0){
      ctx.shadowColor = n >= SELF_IMMUNE_LEN ? '#ffd93d' : s.color;
      ctx.shadowBlur = 8;
    } else {
      ctx.shadowBlur = 0;
    }

    ctx.fillStyle = i === 0 ? s.color : shade(s.color, -0.3);
    roundRect(x + pad, y + pad, CELL - pad * 2, CELL - pad * 2, i === 0 ? 7 : 4);
    ctx.fill();
  }
  ctx.shadowBlur = 0;

  const h = cur[0];
  let hx = h.x * CELL + CELL / 2, hy = h.y * CELL + CELL / 2;
  const headImg = (s.skin === 'gunma') ? getGunmaImg() : null;
  if (headImg && headImg.complete && headImg.naturalWidth){
    ctx.save();
    ctx.globalAlpha = (frozen || stunned) ? 0.45 : 1;
    const hs = CELL * 1.5;
    ctx.drawImage(headImg, hx - hs / 2, hy - hs / 2, hs, hs);
    ctx.restore();
  }
  if (canLerp){
    const p = prev[0];
    const dx = h.x - p.x, dy = h.y - p.y;
    if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1){
      hx = (p.x + dx * t) * CELL + CELL / 2;
      hy = (p.y + dy * t) * CELL + CELL / 2;
    }
  }
  const d = s.dir;
  const perpX = -d.y, perpY = d.x;
  const fx = d.x * CELL * 0.16, fy = d.y * CELL * 0.16;
  const ox = perpX * CELL * 0.2, oy = perpY * CELL * 0.2;

  const hasPhoto = !!(headImg && headImg.complete && headImg.naturalWidth);
  if (!hasPhoto){
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(hx + fx + ox, hy + fy + oy, 2.8, 0, 7); ctx.fill();
  ctx.beginPath(); ctx.arc(hx + fx - ox, hy + fy - oy, 2.8, 0, 7); ctx.fill();
  ctx.fillStyle = '#0a0f1e';
  ctx.beginPath(); ctx.arc(hx + fx + ox + d.x * 1, hy + fy + oy + d.y * 1, 1.4, 0, 7); ctx.fill();
  ctx.beginPath(); ctx.arc(hx + fx - ox + d.x * 1, hy + fy - oy + d.y * 1, 1.4, 0, 7); ctx.fill();
  }

  if (s.isPlayer){
    ctx.font = 'bold 11px system-ui,sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.fillStyle = 'rgba(255,255,255,0.95)';
    ctx.fillText(snakeLabel(s), hx, hy - CELL * 0.8);
  } else if (s.isRemote && s.name && s.name !== 'AI'){
    ctx.font = 'bold 10px system-ui,sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.fillStyle = 'rgba(255,255,255,0.72)';
    ctx.fillText(snakeLabel(s), hx, hy - CELL * 0.8);
  }

  /* 冰冻标记：蛇头旁 ❄ */
  if (frozen){
    ctx.globalAlpha = 1;
    ctx.font = Math.round(CELL * 0.8) + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('❄', hx, hy - CELL * 1.1);
  }
  /* 解冻无敌标记：蛇头旁 🛡（撞谁谁死） */
  if (iceImmuneActive(s)){
    ctx.font = Math.round(CELL * 0.8) + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('🛡', hx, hy - CELL * 1.1);
  }
  /* 红薯熏停标记：蛇头旁 💨 */
  if (stunned){
    ctx.globalAlpha = 1;
    ctx.font = Math.round(CELL * 0.8) + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('💨', hx, hy - CELL * 1.1);
  }
  ctx.globalAlpha = 1;
}

function draw(now){
  const cw = canvas.width, ch = canvas.height;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = '#0a0f1e';
  ctx.fillRect(0, 0, cw, ch);

  if (!S.game) return;
  updateCamera();

  ctx.save();
  ctx.translate(-Math.round(S.camX), -Math.round(S.camY));

  const x0 = Math.floor(S.camX / CELL) - 1;
  const x1 = Math.ceil((S.camX + cw) / CELL) + 1;
  const y0 = Math.floor(S.camY / CELL) - 1;
  const y1 = Math.ceil((S.camY + ch) / CELL) + 1;

  ctx.strokeStyle = 'rgba(90,130,200,0.08)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  const step = 4;
  for (let x = Math.max(0, Math.ceil(x0 / step) * step); x <= x1; x += step){
    if (x < 0 || x > S.world.cols) continue;
    ctx.moveTo(x * CELL + .5, Math.max(0, y0 * CELL));
    ctx.lineTo(x * CELL + .5, Math.min(S.world.rows * CELL, y1 * CELL));
  }
  for (let y = Math.max(0, Math.ceil(y0 / step) * step); y <= y1; y += step){
    if (y < 0 || y > S.world.rows) continue;
    ctx.moveTo(Math.max(0, x0 * CELL), y * CELL + .5);
    ctx.lineTo(Math.min(S.world.cols * CELL, x1 * CELL), y * CELL + .5);
  }
  ctx.stroke();

  ctx.strokeStyle = 'rgba(120,170,255,0.55)';
  ctx.lineWidth = 4;
  ctx.strokeRect(0, 0, S.world.cols * CELL, S.world.rows * CELL);

  ctx.font = Math.round(CELL * 0.86) + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  /* 红薯污染区：9×9 半透明棕橙区域 + 🍠 标识（谁路过谁被熏停 5 秒）
     必须 save/restore 隔离：否则 fillStyle/font/globalAlpha 会泄漏到后面的食物绘制，
     导致全区食物被染成棕阴影（3.0.15 hotfix）。 */
  if (S.game.poisons && S.game.poisons.length){
    ctx.save();
    for (const pz of S.game.poisons){
      const px = (pz.x - POTION_RADIUS) * CELL, py = (pz.y - POTION_RADIUS) * CELL;
      const side = (POTION_RADIUS * 2 + 1) * CELL;
      ctx.fillStyle = 'rgba(194,120,54,0.16)';
      ctx.fillRect(px, py, side, side);
      ctx.strokeStyle = 'rgba(230,150,70,0.5)';
      ctx.lineWidth = 2;
      ctx.strokeRect(px + 1, py + 1, side - 2, side - 2);
      ctx.font = Math.round(CELL * 1.1) + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.globalAlpha = 0.65;
      ctx.fillText('🍠', pz.x * CELL + CELL / 2, pz.y * CELL + CELL / 2);
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  }

  const b0x = Math.floor(x0 / BUCKET_SIZE);
  const b1x = Math.floor(x1 / BUCKET_SIZE);
  const b0y = Math.floor(y0 / BUCKET_SIZE);
  const b1y = Math.floor(y1 / BUCKET_SIZE);

  for (let bx = b0x; bx <= b1x; bx++){
    for (let by = b0y; by <= b1y; by++){
      const set = S.game.foodBuckets.get(bx + ',' + by);
      if (!set) continue;
      for (const f of set){
        if (f.x < x0 || f.x > x1 || f.y < y0 || f.y > y1) continue;
        // 道具=特殊食物类型：按 e 取 emoji（普通食物 / 道具）
        const em = f.e < ITEM_FIRST_E
          ? FOOD_TYPES[f.e]
          : ITEM_EMOJI[ITEM_TYPES[f.e - ITEM_FIRST_E]];
        ctx.fillText(em, f.x * CELL + CELL / 2, f.y * CELL + CELL / 2 + 1);
      }
    }
  }

  /* 地雷放置模式：世界坐标准星 */
  if (S.minePlacing && S.mouse.over){
    const wx = Math.floor((S.camX + S.mouse.x) / CELL);
    const wy = Math.floor((S.camY + S.mouse.y) / CELL);
    if (inBounds(wx, wy)){
      const px = wx * CELL, py = wy * CELL;
      ctx.strokeStyle = isOnSnake(wx, wy) ? 'rgba(255,90,90,0.9)' : 'rgba(120,255,190,0.95)';
      ctx.lineWidth = 2;
      ctx.strokeRect(px + 2, py + 2, CELL - 4, CELL - 4);
      ctx.beginPath();
      ctx.moveTo(px - 8, py + CELL / 2); ctx.lineTo(px + 2, py + CELL / 2);
      ctx.moveTo(px + CELL - 2, py + CELL / 2); ctx.lineTo(px + CELL + 8, py + CELL / 2);
      ctx.moveTo(px + CELL / 2, py - 8); ctx.lineTo(px + CELL / 2, py + 2);
      ctx.moveTo(px + CELL / 2, py + CELL - 2); ctx.lineTo(px + CELL / 2, py + CELL + 8);
      ctx.stroke();
      ctx.font = Math.round(CELL * 0.8) + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('💣', px + CELL / 2, py + CELL / 2);
    }
  }

  const t = clamp((now - S.lastTickTime) / TICK_MS, 0, 1);
  /* 房主权威端：成员蛇在 S.game.remotes，成员端则由 applySnap 放进 g.ai。
     两边都要画出来，否则房主看不到成员的蛇（互相看不见的 bug）。 */
  for (const ai of S.game.ai){
    if (ai.alive && ai.snake.length) drawSnake(ai, t);
  }
  for (const rs of S.game.remotes){
    if (rs.alive && rs.snake.length) drawSnake(rs, t);
  }
  if (S.game.player.alive && S.game.player.snake.length){
    drawSnake(S.game.player, t);
  }

  ctx.restore();
  drawMinimap();
}

function drawMinimap(){
  // 小地图随画布尺寸缩放（手机端更小）
  const size = Math.max(80, Math.min(160, Math.round(Math.min(canvas.width, canvas.height) * 0.3)));
  const pad = 16;
  const mx = canvas.width - size - pad;
  const my = canvas.height - size - pad;

  ctx.fillStyle = 'rgba(10,16,30,0.86)';
  roundRect(mx, my, size, size, 10); ctx.fill();
  ctx.strokeStyle = 'rgba(96,140,210,0.35)';
  ctx.lineWidth = 1;
  roundRect(mx + .5, my + .5, size - 1, size - 1, 10); ctx.stroke();

  if (!S.game) return;
  const k = size / Math.max(S.world.cols, S.world.rows);

  ctx.strokeStyle = 'rgba(255,255,255,0.28)';
  ctx.lineWidth = 1;
  ctx.strokeRect(
    mx + (S.camX / CELL) * k,
    my + (S.camY / CELL) * k,
    (canvas.width / CELL) * k,
    (canvas.height / CELL) * k
  );

  for (const s of allSnakes()){
    if (!s.alive || !s.snake.length) continue;
    ctx.fillStyle = s.skin ? skinColor(s.skin) : s.color;
    ctx.beginPath();
    ctx.arc(mx + (s.snake[0].x + 0.5) * k, my + (s.snake[0].y + 0.5) * k, s.isPlayer ? 4 : 2.6, 0, 7);
    ctx.fill();
    if (s.isPlayer){
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.2;
      ctx.stroke();
    }
  }

  ctx.fillStyle = 'rgba(150,170,200,0.7)';
  ctx.font = '10px system-ui,sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  const p = S.game.player;
  if (p.snake.length){
    ctx.fillText(`(${p.snake[0].x},${p.snake[0].y})`, mx + 6, my + 6);
  }
}

/* ---------------- 渲染循环 ---------------- */
let loopRunning = false;
function startRender(){
  if (loopRunning) return;
  loopRunning = true;
  requestAnimationFrame(renderLoop);
}
function renderLoop(now){
  if (S.screen !== 'game'){ loopRunning = false; return; }
  draw(now);
  updateUI();
  requestAnimationFrame(renderLoop);
}

/* 玩家面板行缓存：sid -> { row, scoreEl, sig }（按 sid 复用 DOM，见 updateUI） */
const panelRowMap = new Map();
let panelOrderSig = ''; // 当前行的排序签名（变化时才移动行）

function updateUI(){
  if (!S.game) return;
  const p = S.game.player;
  const lenEl = document.getElementById('hudLength');
  lenEl.textContent = p.alive ? p.snake.length : 0;
  // 钢筋蛇身状态：HUD 长度变金 + 首次达成提示一次
  const immune = p.alive && p.snake.length >= SELF_IMMUNE_LEN;
  lenEl.classList.toggle('immune', immune);
  if (immune && !S.immuneNotified){
    S.immuneNotified = true;
    toast('🛡 身长达到 ' + SELF_IMMUNE_LEN + '，获得钢筋蛇身：撞到自己不会死了！');
  }
  if (!immune) S.immuneNotified = false;
  // 胜利目标长度
  document.getElementById('hudWinTarget').textContent = '/' + S.winLen;

  const alive = allSnakes().filter(s => s.alive);
  const sorted = [...alive].sort((a, b) => b.score - a.score || b.snake.length - a.snake.length);
  const rank = sorted.indexOf(p) + 1;
  document.getElementById('hudRank').textContent = p.alive ? rank : '-';
  document.getElementById('hudTotal').textContent = alive.length;

  // 倍速 HUD：自己的蛇速 != 1 时显示（全局速度不变，只是自己快）
  const mySp = effectiveSpeed(p);
  const hudSpeed = document.getElementById('hudSpeed');
  if (hudSpeed){
    if (mySp !== 1){ hudSpeed.hidden = false; hudSpeed.textContent = '⚡×' + mySp; }
    else hudSpeed.hidden = true;
  }
  refreshSpeedPanel();
  refreshItemBar();
  /* 聊天：分钟清除 + 可见性/定位同步 */
  chatPurgeTick();
  chatSyncPerFrame();

  /* 玩家面板：按 sid 复用行 DOM，绝不每帧 innerHTML 重建。
     每帧重建会销毁按钮——mousedown 后到 mouseup 前元素已被替换，
     click 事件不触发，表现为「管理点不动」。 */
  const panel = document.getElementById('playersPanel');
  const list = allSnakes().filter(s => s.alive || s.isPlayer || s.isRemote);
  const sorted2 = [...list].sort((a, b) => b.score - a.score);
  const seenIds = new Set();
  const seenMids = new Set();
  for (const s of sorted2){
    seenIds.add(s.sid);
    const mid = s.memberNo || s.sid;
    const isHostView = S.online && S.role === 'host';
    const canManage = isHostView && s.isRemote && !s.isHost;
    if (canManage) seenMids.add(mid);
    /* 管理（被赠神器的成员）视角：可禁言其他成员（不含房主/自己/AI） */
    const iAmAdmin = S.online && S.role === 'guest' && !!(p && p.gifted);
    const canMute = iAmAdmin && s.isRemote && !s.isHost && !s.isPlayer
      && typeof s.memberNo === 'number';
    /* 组队邀请：可邀请人类玩家（非自己、非队友、两边队伍都未满） */
    const myT = myTeamId();
    const sT = s.team || 0;
    const canInvite = S.online && S.screen === 'game' && !s.isPlayer
      && (s.isRemote || s.isHost) && sT !== myT
      && (!myT || teamSize(myT) < TEAM_MAX)
      && (!sT || teamSize(sT) < TEAM_MAX);
    /* 行结构签名：只在这些属性变化时才重建行内容 */
    const rowSig = [
      s.isPlayer ? 1 : 0, s.isRemote ? 1 : 0, s.isHost ? 1 : 0,
      s.alive ? 1 : 0, s.crowns || 0, canManage ? 1 : 0, canMute ? 1 : 0,
      s.muted ? 1 : 0, sT, canInvite ? 1 : 0,
      s.color, snakeLabel(s),
    ].join('|');
    let rec = panelRowMap.get(s.sid);
    const isNewRow = !rec;
    if (!rec){
      rec = { row: document.createElement('div'), scoreEl: null, sig: '' };
      panelRowMap.set(s.sid, rec);
    }
    if (rec.sig !== rowSig){
      rec.sig = rowSig;
      const name = escapeHtml(snakeLabel(s));
      const crown = (s.crowns || 0) > 0
        ? `<span class="pp-crown" title="本局累计夺冠 ${s.crowns} 次">👑${s.crowns}</span>` : '';
      const muted = s.muted ? `<span class="pp-muted" title="已被禁言，聊天关闭">🔇</span>` : '';
      const teamBadge = sT
        ? `<span class="pp-team" style="background:${teamColor(sT)}" title="队伍${teamLetter(sT)}${sT === myT ? '（你的队伍：互撞不死、不能互冻、可碰醒队友）' : ''}">${teamLetter(sT)}</span>`
        : '';
      /* 管理按钮：菜单本体是 fixed 浮动元素（见 openManageMenu）——
          行内 absolute 菜单会被面板 overflow-y:auto 裁掉（底部成员
          点开只看到半截，「没有黑屏按键」就是这么来的） */
      const mgr = canManage
        ? `<button class="pp-manage" data-mid="${mid}" title="管理该成员">管理</button>`
        : '';
      /* 管理身份成员的禁言按钮（成员视角）：发给房主权威执行 */
      const muteBtn = canMute
        ? `<button class="pp-mute" data-sid="${s.sid}" title="${s.muted ? '已被禁言（仅房主可解禁）' : '禁言该成员'}">🔇</button>`
        : '';
      /* 组队邀请按钮（联机对局中）：一队最多 3 人 */
      const invBtn = canInvite
        ? `<button class="pp-invite" data-sid="${s.sid}" title="邀请组队（一队最多 ${TEAM_MAX} 人）">🤝</button>`
        : '';
      rec.row.className = `pp-row ${s.isPlayer ? 'me' : ''} ${s.alive ? '' : 'dead'} ${s.muted ? 'muted' : ''}`;
      rec.row.dataset.sid = s.sid; // hover 详情委托靠它定位行（sid 不变，设一次即可）
      rec.row.innerHTML = `
        <span class="pp-dot" style="background:${s.color}"></span>
        <span class="pp-nick">${name}</span>
        ${crown}
        ${muted}
        ${teamBadge}
        <span class="pp-score"></span>
        ${muteBtn}${invBtn}${mgr}`;
      rec.scoreEl = rec.row.querySelector('.pp-score');
    }
    /* 分数高频变化：只更新文本，不动 DOM 结构 */
    if (rec.scoreEl) rec.scoreEl.textContent = s.score;
    if (isNewRow) panel.appendChild(rec.row); // 新行立即入列
  }
  /* 排序变化时才移动行；菜单打开/hover 详情期间冻结（移动行会中断进行中的点击）。
     已存在的节点仅调整顺序，不重建。 */
  if (S.manageOpen === null && hoverSid === null){
    const orderSig = sorted2.map(s => s.sid).join(',');
    if (orderSig !== panelOrderSig){
      panelOrderSig = orderSig;
      for (const s of sorted2) panel.appendChild(panelRowMap.get(s.sid).row);
    }
  }
  // 移除离场玩家的行
  for (const [sid, rec] of Array.from(panelRowMap)){
    if (!seenIds.has(sid)){
      if (hoverSid === sid) hideRowDetail();
      if (manageMenuRow === rec.row) hideManageMenu();
      if (rec.row.remove) rec.row.remove();
      panelRowMap.delete(sid);
    }
  }
  // 管理菜单指向的成员已离场：收起菜单
  if (S.manageOpen !== null && !seenMids.has(S.manageOpen)) hideManageMenu();

  // 联机状态
  const hudOnline = document.getElementById('hudOnline');
  if (S.online){
    hudOnline.hidden = false;
    document.getElementById('hudOnlineCount').textContent = S.role === 'host'
      ? allSnakes().length
      : 1 + S.game.ai.length;
    document.getElementById('hudOnlineRole').textContent = (S.role === 'host' ? '房主' : '成员') + (S.serverMode ? '·服务器' : '');
    document.getElementById('hudRoomNo').textContent = S.roomNo ? ' · 房号 ' + S.roomNo : '';
  } else {
    hudOnline.hidden = true;
  }

  const ov = document.getElementById('respawnOverlay');
  if (p.alive){
    ov.classList.remove('show');
  } else {
    const remain = Math.max(0, (p.respawnAt - performance.now()) / 1000);
    document.getElementById('respawnCount').textContent = remain.toFixed(1);
    ov.classList.add('show');
  }

  updateSnakeInfo();
  refreshRowDetail();
  refreshManageMenu();
  refreshCompTimer();
}

/* =========================================================
   鼠标靠近某条蛇：屏幕左侧弹出该蛇信息卡
   （靠近 = 蛇头 8 格内，或身体抽样 8 格内；pointer-events 穿透不挡操作）
   ========================================================= */
let infoSid = null;
let infoStatusEl = null;
function updateSnakeInfo(){
  const box = document.getElementById('snakeInfo');
  if (!box) return;
  let target = null;
  if (S.game && S.mouse.over && S.screen === 'game'){
    const wx = (S.camX + S.mouse.x) / CELL;
    const wy = (S.camY + S.mouse.y) / CELL;
    let bestD2 = 8 * 8;
    for (const s of allSnakes()){
      if (!s.alive || !s.snake.length) continue;
      const h = s.snake[0];
      const d2 = (h.x - wx) * (h.x - wx) + (h.y - wy) * (h.y - wy);
      if (d2 < bestD2){ bestD2 = d2; target = s; continue; }
      // 头部不够近时抽样扫身体（每 4 节取 1），长蛇开销可控
      for (let i = 4; i < s.snake.length; i += 4){
        const b = s.snake[i];
        const b2 = (b.x - wx) * (b.x - wx) + (b.y - wy) * (b.y - wy);
        if (b2 < bestD2){ bestD2 = b2; target = s; break; }
      }
    }
  }
  if (!target){
    if (infoSid !== null){ infoSid = null; infoStatusEl = null; box.classList.remove('show'); }
    return;
  }
  if (infoSid !== target.sid){
    infoSid = target.sid;
    box.innerHTML = `
      <div class="si-head">
        <span class="si-dot" style="background:${target.color}"></span>
        <span class="si-name">${escapeHtml(snakeLabel(target))}</span>
      </div>
      <div class="si-grid">
        <span>得分</span><b>${target.score}</b>
        <span>长度</span><b>${target.alive ? target.snake.length : 0}</b>
        <span>状态</span><b class="si-status">存活</b>
        <span>皮肤</span><b>${skinOf(target.skin).name}</b>
        <span>队伍</span><b>${target.team ? "队" + target.team : "无"}</b>
        ${(target.crowns || 0) > 0 ? `<span>皇冠</span><b>👑${target.crowns}</b>` : ''}
      </div>`;
    infoStatusEl = box.querySelector('.si-status');
  }
  // 重生倒计时需要逐帧刷新
  if (!target.alive && infoStatusEl){
    infoStatusEl.textContent = '重生中 ' + Math.max(0, (target.respawnAt - performance.now()) / 1000).toFixed(1) + 's';
  } else if (target.alive && infoStatusEl){
    let st = '存活';
    if (frozenActive(target)) st = '🧊 冰冻中';
    else if (orangeActive(target)) st = '🍊 狂暴中';
    else if (slowActive(target)) st = '💥 减速中';
    infoStatusEl.textContent = st;
  }
  box.classList.add('show');
}

/* =========================================================
   玩家面板 hover 详情：鼠标靠近（悬停）某个成员行，
   在该行左侧弹出完整信息卡（面板 overflow-y:auto 会裁行内卡片，
   故用 fixed 独立元素 + getBoundingClientRect 定位到行旁）
   ========================================================= */
let hoverSid = null;
let hoverDetailEl = null;
let hoverScoreEl = null, hoverLenEl = null, hoverStatusEl = null;
let hoverRowEl = null;
let hoverSig = '';

function getDetailBox(){
  if (!hoverDetailEl){
    hoverDetailEl = document.createElement('div');
    hoverDetailEl.className = 'pp-detail';
    document.body.appendChild(hoverDetailEl);
  }
  return hoverDetailEl;
}

function showRowDetail(sid){
  const id = Number(sid);
  if (!Number.isFinite(id)) return;
  const rec = panelRowMap.get(id);
  if (!rec || !rec.row) return;
  const s = allSnakes().find(x => x.sid === id);
  if (!s){ hideRowDetail(); return; }
  hoverSid = id;
  hoverRowEl = rec.row;
  const box = getDetailBox();
  /* 结构签名变化才重建内容（皇冠数/昵称/身份变色时） */
  const sig = [id, s.crowns || 0, snakeLabel(s), s.color].join('|');
  if (hoverSig !== sig){
    hoverSig = sig;
    const name = escapeHtml(snakeLabel(s));
    const crown = (s.crowns || 0) > 0
      ? `<span>皇冠</span><b>👑${s.crowns}</b>` : '';
    box.innerHTML = `
      <div class="pd-head">
        <span class="pd-dot" style="background:${s.color}"></span>
        <span class="pd-name">${name}</span>
      </div>
      <div class="pd-grid">
        <span>得分</span><b class="pd-score"></b>
        <span>长度</span><b class="pd-len"></b>
        <span>状态</span><b class="pd-status"></b>
        ${crown}
      </div>`;
    hoverScoreEl = box.querySelector('.pd-score');
    hoverLenEl = box.querySelector('.pd-len');
    hoverStatusEl = box.querySelector('.pd-status');
  }
  box.classList.add('show');
  refreshRowDetail();
}

function hideRowDetail(){
  hoverSid = null;
  hoverRowEl = null;
  hoverSig = '';
  if (hoverDetailEl){
    hoverDetailEl.classList.remove('show');
    hoverDetailEl.dataset.sid = '';
  }
}

function refreshRowDetail(){
  if (hoverSid === null || !hoverDetailEl) return;
  const s = allSnakes().find(x => x.sid === hoverSid);
  if (!s){ hideRowDetail(); return; }
  if (hoverScoreEl) hoverScoreEl.textContent = s.score;
  if (hoverLenEl) hoverLenEl.textContent = s.alive ? s.snake.length : 0;
  if (hoverStatusEl){
    hoverStatusEl.textContent = s.alive
      ? (frozenActive(s) ? '🧊 冰冻中' : (orangeActive(s) ? '🍊 狂暴中' : (slowActive(s) ? '💥 减速中' : '存活')))
      : '重生中 ' + Math.max(0, (s.respawnAt - performance.now()) / 1000).toFixed(1) + 's';
  }
  /* 位置跟随行（fixed 用视口坐标；排序变化/面板滚动每帧校正） */
  if (hoverRowEl && hoverRowEl.getBoundingClientRect){
    const r = hoverRowEl.getBoundingClientRect();
    if (!r.height && !r.width){ hideRowDetail(); return; } // 行已不可见（离场/画面切换）
    hoverDetailEl.style.right = (window.innerWidth - r.left + 10) + 'px';
    hoverDetailEl.style.top = (r.top + r.height / 2) + 'px';
  }
}

/* =========================================================
   房主管理菜单：fixed 浮动元素（挂在 body 下）
   行内 absolute 菜单会被 .players-panel 的 overflow-y:auto 裁剪——
   底部成员行点「管理」只露出半截甚至整体在可视区外，
   表现为「打不开 / 没有黑屏按键」。fixed + 每帧定位到行旁解决。
   ========================================================= */
let manageMenuEl = null;
let manageMenuRow = null; // 定位基准行（行被移除/离场时收起）

function getManageMenu(){
  if (!manageMenuEl){
    manageMenuEl = document.createElement('div');
    manageMenuEl.className = 'pp-menu-float';
    manageMenuEl.innerHTML = `
      <button class="pp-menu-item" data-act="reset">🔄 重置</button>
      <button class="pp-menu-item" data-act="black">🌑 黑屏</button>
      <button class="pp-menu-item" data-act="mute">🔇 禁言</button>
      <button class="pp-menu-item danger" data-act="kick">⛔ 踢出</button>
      <button class="pp-menu-item gift" data-act="gift">🎁 赠送神器</button>`;
    document.body.appendChild(manageMenuEl);
    manageMenuEl.addEventListener('click', e => {
      const item = e.target && e.target.closest ? e.target.closest('.pp-menu-item') : null;
      if (!item) return;
      const mid = +item.dataset.mid;
      const act = item.dataset.act;
      hideManageMenu();
      if (Number.isFinite(mid) && act) manageMember(mid, act);
    });
  }
  return manageMenuEl;
}

function openManageMenu(mid, row){
  S.manageOpen = mid;
  manageMenuRow = row || null;
  const box = getManageMenu();
  const items = box.querySelectorAll('.pp-menu-item');
  for (let i = 0; i < items.length; i++) items[i].dataset.mid = mid;
  /* 赠送/收回、禁言/解禁文案随该成员当前状态切换 */
  const rs = S.netPeers.get(mid);
  const giftBtn = box.querySelector('[data-act="gift"]');
  if (giftBtn) giftBtn.textContent = (rs && rs.gifted) ? '💫 收回神器' : '🎁 赠送神器';
  const muteBtn = box.querySelector('[data-act="mute"]');
  if (muteBtn) muteBtn.textContent = (rs && rs.muted) ? '🔊 解禁' : '🔇 禁言';
  box.classList.add('show');
  refreshManageMenu();
}

function hideManageMenu(){
  S.manageOpen = null;
  manageMenuRow = null;
  if (manageMenuEl) manageMenuEl.classList.remove('show');
}

function refreshManageMenu(){
  if (S.manageOpen === null || !manageMenuEl || !manageMenuRow) return;
  const r = manageMenuRow.getBoundingClientRect ? manageMenuRow.getBoundingClientRect() : null;
  if (!r || (!r.height && !r.width)){ hideManageMenu(); return; } // 行已离场不可见
  const h = manageMenuEl.offsetHeight || 104;
  manageMenuEl.style.right = (window.innerWidth - r.right + 6) + 'px';
  if (r.bottom + h + 12 <= window.innerHeight){
    manageMenuEl.style.top = (r.bottom + 4) + 'px';   // 默认下弹
    manageMenuEl.style.bottom = 'auto';
  } else {
    manageMenuEl.style.top = 'auto';                  // 贴近屏幕底部：改为上弹
    manageMenuEl.style.bottom = (window.innerHeight - r.top + 4) + 'px';
  }
}

/* =========================================================
   房主管理成员：重置 / 黑屏（开关式）/ 踢出
   ========================================================= */
function manageMember(peerId, act){
  if (S.role !== 'host' || !S.online) return;
  const rs = S.netPeers.get(peerId);
  if (act === 'reset'){
    if (rs && S.game){
      respawnSnake(rs);   // 权威端直接重生，下一 tick 快照同步到该成员
      toast(`已将 成员${peerId} 的蛇重置重生`);
    }
  } else if (act === 'black'){
    if (rs){
      rs.blackout = !rs.blackout;
      Net.sendToPeer(peerId, { t: 'blackout', on: !!rs.blackout });
      toast(rs.blackout ? `成员${peerId} 已被黑屏` : `成员${peerId} 黑屏已恢复`);
    }
  } else if (act === 'mute'){
    /* 禁言/解禁：房主可禁言任意成员，也可解除任何人（含管理禁言的）的禁言 */
    if (rs){
      rs.muted = !rs.muted;
      toast(rs.muted
        ? `🔇 成员${peerId} 已被禁言（聊天关闭）`
        : `🔊 成员${peerId} 已解除禁言`);
    }
  } else if (act === 'kick'){
    if (rs){
      Net.sendToPeer(peerId, { t: 'kicked' });
      Net.closePeer(peerId);   // P2P：关 DataChannel；服务器模式：服务器断开该成员
      toast(`成员${peerId} 已被踢出`);
    }
  } else if (act === 'gift'){
    /* 赠送神器：该成员获得不死之身 + 磁吸食物 + 倍速（初始 ×1，可自调） */
    if (rs){
      rs.gifted = !rs.gifted;
      if (!rs.gifted) rs.speed = 1;   // 收回神器：倍速复位
      Net.sendToPeer(peerId, { t: 'gift', on: !!rs.gifted, speed: rs.speed });
      toast(rs.gifted
        ? `🎁 成员${peerId} 获得神器：不死之身 + 磁吸食物 + 倍速`
        : `已收回 成员${peerId} 的神器`);
    }
  }
  hideManageMenu();
}

/* 玩家面板事件委托（面板每帧重建，菜单开合状态存 S.manageOpen） */
const playersPanelEl = document.getElementById('playersPanel');
playersPanelEl.addEventListener('click', e => {
  /* 组队邀请按钮（联机对局中）：房主直发 / 成员经房主转发 */
  const invBtn = e.target.closest('.pp-invite');
  if (invBtn){
    sendTeamInvite(Number(invBtn.dataset.sid));
    return;
  }
  /* 管理身份：禁言按钮（成员视角，发给房主权威执行） */
  const muteBtn = e.target.closest('.pp-mute');
  if (muteBtn){
    const sid = Number(muteBtn.dataset.sid);
    const target = allSnakes().find(s => s.sid === sid);
    if (target && target.muted){ toast('该成员已被禁言（仅房主可解禁）'); return; }
    Net.sendToHost({ t: 'mute', sid: sid });
    toast('🔇 已请求禁言 ' + (target ? snakeLabel(target) : '该成员'));
    return;
  }
  const btn = e.target.closest('.pp-manage');
  if (btn){
    const mid = +btn.dataset.mid;
    if (S.manageOpen === mid){
      hideManageMenu();
    } else {
      openManageMenu(mid, btn.closest('.pp-row'));
    }
    return;
  }
  /* 点行空白处：触屏设备上切换该成员详情卡（桌面由 hover 触发） */
  const row = e.target.closest('.pp-row');
  if (row && playersPanelEl.contains(row)){
    const id = Number(row.dataset.sid);
    if (hoverSid === id) hideRowDetail(); else showRowDetail(id);
  }
  if (S.manageOpen !== null) hideManageMenu(); // 点了别处：收起管理菜单
});

/* 点面板/菜单之外的区域也收起管理菜单（fixed 菜单挂在 body 下） */
document.addEventListener('click', e => {
  if (S.manageOpen === null) return;
  const t = e.target;
  if (t && t.closest && (t.closest('.pp-manage') || t.closest('.pp-menu-float'))) return;
  hideManageMenu();
});

/* hover 详情（事件委托：行按 sid 复用，监听器不丢） */
playersPanelEl.addEventListener('mouseover', e => {
  const row = e.target && e.target.closest ? e.target.closest('.pp-row') : null;
  if (!row || !playersPanelEl.contains(row)) return;
  showRowDetail(row.dataset.sid);
});
playersPanelEl.addEventListener('mouseout', e => {
  const row = e.target && e.target.closest ? e.target.closest('.pp-row') : null;
  if (!row) return;
  const to = e.relatedTarget;
  if (to && row.contains(to)) return; // 行内子元素间移动不收起
  hideRowDetail();
});

/* =========================================================
   食物密度设置 UI
   ========================================================= */
const foodMinInput = document.getElementById('foodMin');
const foodMaxInput = document.getElementById('foodMax');
const minValueEl = document.getElementById('minValue');
const maxValueEl = document.getElementById('maxValue');
const summaryEl = document.getElementById('settingSummary');

function refreshSettingUI(){
  minValueEl.textContent = S.foodMin;
  maxValueEl.textContent = S.foodMax;
  foodMinInput.value = S.foodMin;
  foodMaxInput.value = S.foodMax;
  summaryEl.innerHTML = `当前设置：每 25 格 <b>${S.foodMin} ~ ${S.foodMax}</b> 个食物`;

  // 同步滑块样式（用渐变填充表示选择范围）
  updateSliderFill(foodMinInput);
  updateSliderFill(foodMaxInput);
  refreshWinLenUI();
}

function updateSliderFill(input){
  const min = +input.min, max = +input.max, v = +input.value;
  const pct = ((v - min) / (max - min)) * 100;
  input.style.background = `linear-gradient(to right, #3ecf8e 0%, #2aa9e0 ${pct}%, rgba(96,140,210,.3) ${pct}%, rgba(96,140,210,.3) 100%)`;
}

