/* =========================================================
   游戏控制
   ========================================================= */
function startGame(){
  S.winner = null;
  S.winHint = 0;
  S.pendingWelcome = false;
  S.minePlacing = false;
  hideIcePicker();
  hideItemHelp();
  document.getElementById('winOverlay').classList.remove('show');
  if (!S.game) createGame();
  // 新对局：快照世界尺寸基线复位（加长扩界才会重发）
  S.snapWorldCols = S.world.cols;
  S.snapWorldRows = S.world.rows;
  resizeCanvas();
  showScreen('game');
  S.paused = false;
  document.getElementById('pauseOverlay').classList.remove('show');
  // HUD 显示当前食物设置与胜利长度
  document.getElementById('hudFoodRange').textContent = `${S.foodMin}~${S.foodMax}`;
  document.getElementById('hudWinTarget').textContent = '/' + S.winLen;
  if (S.online) S.enteredGame = true;
  refreshPauseBtn();
  refreshMapUI();
  // 竞赛模式：房主端开始计时并广播（成员端由 applyComp 同步）
  if (S.online && S.role === 'host') startCompetition();

  if (S.tickTimer) clearInterval(S.tickTimer);
  // 成员端不跑本地模拟（权威在房主），只接收快照渲染
  if (!(S.online && S.role === 'guest')){
    S.tickTimer = setInterval(tick, TICK_MS);
  }
  startRender();
}

function stopGame(){
  if (S.tickTimer){ clearInterval(S.tickTimer); S.tickTimer = null; }
  S.game = null;
  loopRunning = false;
}

function backToMenu(){
  stopGame();
  document.getElementById('awayOverlay').classList.remove('show');
  if (S.online && S.role === 'host'){
    // 房主暂离：P2P 连接保持，通知成员等待（房主随时可返回）
    Net.broadcast({ t: 'hostAway', on: true });
  } else if (S.online && S.role === 'guest'){
    // 成员退出游戏：通知房主清除管理身份（连接保持，可从房间条返回）
    Net.sendToHost({ t: 'exit' });
  }
  showScreen('menu');
  refreshRoomBar();
}

function togglePause(){
  if (!S.game || S.winner) return;
  // 成员端无暂停权限（按钮已隐藏，P/空格同样不响应）
  if (S.online && S.role === 'guest') return;
  if (S.online){
    setPaused(!S.paused);
    Net.broadcast({ t: 'pause', on: S.paused });
    return;
  }
  setPaused(!S.paused);
}

function setPaused(on){
  S.paused = !!on;
  const ov = document.getElementById('pauseOverlay');
  if (S.paused) ov.classList.add('show');
  else ov.classList.remove('show');
}

/* =========================================================
   输入
   ========================================================= */
const KEYMAP = {
  ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
  w: 'up', s: 'down', a: 'left', d: 'right',
  W: 'up', S: 'down', A: 'left', D: 'right',
};

function sendDir(d){
  if (!S.game || S.paused || S.winner) return;
  const dir = DIRS[d];
  if (!dir) return;
  const p = S.game.player;
  if (dir.x === -p.dir.x && dir.y === -p.dir.y) return;
  if (S.online){
    if (S.role === 'guest'){
      // 成员端：只把方向发给房主，由房主权威模拟
      if (!p.alive) return;
      Net.sendToHost({ t: 'input', d });
    } else {
      if (!p.alive) return;
      p.nextDir = dir;
    }
    return;
  }
  if (!p.alive) return;
  p.nextDir = dir;
}

window.addEventListener('keydown', e => {
  if (S.screen !== 'game') return;
  // 聊天输入框中打字：不触发方向键/暂停（输入框自身监听也会 stopPropagation）
  const ae = document.activeElement;
  if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA')) return;
  if (e.key === 'Escape'){
    // Esc：取消地雷放置 / 关闭道具弹窗
    if (S.minePlacing) cancelMinePlace();
    hideIcePicker();
    hideItemHelp();
    return;
  }
  if (e.key === ' ' || e.key === 'p' || e.key === 'P'){
    e.preventDefault();
    togglePause();
    return;
  }
  const d = KEYMAP[e.key];
  if (d){ e.preventDefault(); sendDir(d); }
}, { passive: false });

let touchStart = null;
canvas.addEventListener('touchstart', e => {
  const t = e.touches[0];
  touchStart = { x: t.clientX, y: t.clientY };
}, { passive: true });
canvas.addEventListener('touchmove', e => { e.preventDefault(); }, { passive: false });
canvas.addEventListener('touchend', e => {
  if (!touchStart) return;
  const t = e.changedTouches[0];
  const dx = t.clientX - touchStart.x, dy = t.clientY - touchStart.y;
  touchStart = null;
  if (Math.abs(dx) < 18 && Math.abs(dy) < 18) return;
  if (Math.abs(dx) > Math.abs(dy)) sendDir(dx > 0 ? 'right' : 'left');
  else sendDir(dy > 0 ? 'down' : 'up');
}, { passive: true });

/* 鼠标位置：靠近蛇身时左侧弹信息卡（canvas 样式尺寸与像素 1:1，无需缩放） */
canvas.addEventListener('mousemove', e => {
  const r = canvas.getBoundingClientRect();
  S.mouse.x = e.clientX - r.left;
  S.mouse.y = e.clientY - r.top;
  S.mouse.over = true;
});
canvas.addEventListener('mouseleave', () => { S.mouse.over = false; });

/* 地雷放置模式：点击地图安放（隐形） */
canvas.addEventListener('mousedown', e => {
  if (!S.minePlacing || S.screen !== 'game' || !S.game) return;
  e.preventDefault();
  const r = canvas.getBoundingClientRect();
  const wx = Math.floor((S.camX + (e.clientX - r.left)) / CELL);
  const wy = Math.floor((S.camY + (e.clientY - r.top)) / CELL);
  placeMineAt(wx, wy);
});
canvas.addEventListener('contextmenu', e => {
  if (S.minePlacing){ e.preventDefault(); cancelMinePlace(); }
});

